insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('sunday-reset-review-planner', 'Sunday Reset Review Planner', 'worksheet'::resource_kind, 'A one-page look back at the week that sorts what worked, what drained, and one change to try next.', 'Help a client turn a whole week into one small, doable adjustment.', array['Adults']::text[], '15 minutes', 'Use this at the start or end of a session when a client describes the week as a blur. The three-part sort keeps the review balanced, so wins are named alongside the hard parts. Watch for clients who list only problems; ask for one small thing that went a little better. Keep the next-week change to a single step.', '[{"id": "f0", "type": "textarea", "label": "The moments this week that went better than I expected"}, {"id": "f1", "type": "textarea", "label": "The moments that drained me most"}, {"id": "f2", "type": "textarea", "label": "What I needed more of this week"}, {"id": "f3", "type": "textarea", "label": "What I needed less of this week"}, {"id": "f4", "type": "textarea", "label": "One small change I will try next week"}, {"id": "f5", "type": "textarea", "label": "Who or what could help me keep that change going"}]'::jsonb, array['monitoring', 'routines', 'skills']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('conversation-rehearsal-planner', 'Conversation Rehearsal Planner', 'worksheet'::resource_kind, 'A planner for a hard conversation: the goal, the opening line, likely replies, and a plan for staying steady.', 'Prepare a client to say something difficult in their own words.', array['Adults', 'Teens']::text[], '30 minutes', 'Run this before a conversation the client has been avoiding. Role-play the opening line in session, then trade places so they hear the other person''s likely replies. It works best when the goal is about being clear, not about controlling how the other person responds. Check that the plan includes an exit if the talk heats up.', '[{"id": "f0", "type": "textarea", "label": "The conversation I want to have, and with whom"}, {"id": "f1", "type": "textarea", "label": "What I most want the other person to understand"}, {"id": "f2", "type": "textarea", "label": "My opening sentence, in my own words"}, {"id": "f3", "type": "textarea", "label": "What they might say back"}, {"id": "f4", "type": "textarea", "label": "How I will stay steady if it gets tense"}, {"id": "f5", "type": "textarea", "label": "How I will end the conversation if I need a break"}, {"id": "f6", "type": "textarea", "label": "How I will take care of myself afterward"}]'::jsonb, array['communication', 'assertiveness', 'skills']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('big-change-transition-plan', 'Big Change Transition Plan', 'worksheet'::resource_kind, 'A plan for a life change that names what ends, what continues, and what support to line up.', 'Give a client a steady structure during a move, job change, or other shift.', array['Adults']::text[], 'Full session', 'Big changes often bring a mix of loss and hope in the same week. Let the client fill in the left side, what is ending, before the right side, what is starting, so the loss is not skipped. Pay attention to the Continues column; clients are often surprised by how much stays the same. Revisit the support list over the next few sessions.', '[{"id": "f0", "type": "textarea", "label": "The change I am going through"}, {"id": "f1", "type": "textarea", "label": "What is ending or being left behind"}, {"id": "f2", "type": "textarea", "label": "What is staying the same"}, {"id": "f3", "type": "textarea", "label": "What is beginning"}, {"id": "f4", "type": "textarea", "label": "What feels hardest about the first month"}, {"id": "f5", "type": "textarea", "label": "The people I can lean on"}, {"id": "f6", "type": "textarea", "label": "One small routine I want to keep through the change"}]'::jsonb, array['support', 'routines', 'values']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('rest-types-menu', 'Rest Types Menu', 'worksheet'::resource_kind, 'A menu of different kinds of rest (physical, mental, social, sensory, creative) for choosing what actually refills a client.', 'Help a client match the kind of rest to the kind of tiredness.', array['Adults']::text[], '20 minutes', 'Many clients assume rest means sleep or screens and stay tired. Walk through the rest types together and have them rate which they get least. Ask about the difference between rest that refills and rest that only numbs. Keep choices small and specific, and ask them to try one this week and report back.', '[{"id": "f0", "type": "textarea", "label": "The kind of tired I feel most often"}, {"id": "f1", "type": "textarea", "label": "The kind of rest I get the least of"}, {"id": "f2", "type": "textarea", "label": "A way I could get physical rest this week"}, {"id": "f3", "type": "textarea", "label": "A way I could rest my mind"}, {"id": "f4", "type": "textarea", "label": "A way I could rest my senses, like quiet or dim light"}, {"id": "f5", "type": "textarea", "label": "A kind of rest that looks like rest but leaves me still tired"}, {"id": "f6", "type": "textarea", "label": "The one rest I will try this week"}]'::jsonb, array['routines', 'self-monitoring', 'coping skills']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('thank-you-and-recognition-log', 'Thank-You and Recognition Log', 'worksheet'::resource_kind, 'A weekly log of thanks given, thanks received, and quiet efforts a client noticed in others and in themselves.', 'Build the habit of noticing effort and kindness in daily life.', array['Adults', 'Teens']::text[], 'Five minutes daily for one week', 'Use this with clients whose attention drifts to what is missing. The log has three directions: thanks they gave, thanks they received, and effort they noticed but did not mention. Keep entries concrete and brief. If a client dismisses their own entries, invite them to record what a friend would have noticed.', '[{"id": "f0", "type": "textarea", "label": "Someone I thanked or could thank this week"}, {"id": "f1", "type": "textarea", "label": "Something kind someone did for me"}, {"id": "f2", "type": "textarea", "label": "An effort I noticed in someone else"}, {"id": "f3", "type": "textarea", "label": "An effort I made that I almost overlooked"}, {"id": "f4", "type": "textarea", "label": "How it felt to notice these"}, {"id": "f5", "type": "textarea", "label": "Someone I could tell this week how much it mattered"}]'::jsonb, array['connection', 'self-monitoring', 'values']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('mind-reading-reality-check-card', 'Mind Reading Reality Check Card', 'cbt'::resource_kind, 'A sheet that separates what a client knows about another person''s thoughts from what they are guessing.', 'Help a client test a guess about others'' thoughts against what is actually known.', array['Adults', 'Teens']::text[], '20 minutes', 'Mind reading shows up in social worries, conflicts, and low mood alike. Have the client write the guess, then list what they actually observed, then at least two other explanations. It is not about proving the guess wrong; it is about loosening certainty. Offer a small way to check in with the person when that is safe.', '[{"id": "f0", "type": "textarea", "label": "What I think the other person is thinking"}, {"id": "f1", "type": "textarea", "label": "What I actually saw or heard"}, {"id": "f2", "type": "textarea", "label": "How sure I am, from 0 to 100"}, {"id": "f3", "type": "textarea", "label": "Two other explanations that could fit"}, {"id": "f4", "type": "textarea", "label": "What I could ask or check, if it is safe to"}, {"id": "f5", "type": "textarea", "label": "How sure I am now, from 0 to 100"}]'::jsonb, array['thinking traps', 'core CBT', 'social anxiety']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('should-to-could-rewrite-sheet', 'Should-to-Could Rewrite Sheet', 'cbt'::resource_kind, 'A sheet that turns rigid shoulds and musts into flexible preferences a client can live with.', 'Loosen rigid rules a client holds about themselves and others.', array['Adults']::text[], '20 minutes', 'Notice the words should, must, and have to in a client''s speech and bring a few to the page. Ask what the rule is protecting, then draft a softer version such as I would prefer or it would help if. The aim is flexibility, not lowering standards. Ask what the rule costs the client in daily life and in relationships.', '[{"id": "f0", "type": "textarea", "label": "A should or must I say to myself often"}, {"id": "f1", "type": "textarea", "label": "Where I learned that rule"}, {"id": "f2", "type": "textarea", "label": "What the rule is trying to protect"}, {"id": "f3", "type": "textarea", "label": "What it costs me day to day"}, {"id": "f4", "type": "textarea", "label": "My rewrite, using prefer, want, or would help"}, {"id": "f5", "type": "textarea", "label": "How I might act differently with the new wording"}]'::jsonb, array['thinking traps', 'core CBT', 'core beliefs']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('emotional-reasoning-reality-check', 'Emotional Reasoning Reality Check', 'cbt'::resource_kind, 'A sheet for the moment a feeling is treated as a fact, with space to separate what is felt from what is known.', 'Help a client notice when a strong feeling is standing in for evidence.', array['Adults', 'Teens']::text[], '20 minutes', 'Emotional reasoning sounds like I feel like a failure, so I am one. Use a recent example and ask the client to write the feeling and the conclusion separately. The point is not to argue with the feeling, which is real, but to see that the conclusion needs its own look. Pair it with a record of what actually happened.', '[{"id": "f0", "type": "textarea", "label": "The feeling I had, and how strong it was"}, {"id": "f1", "type": "textarea", "label": "The conclusion my feeling pushed me toward"}, {"id": "f2", "type": "textarea", "label": "The facts I can point to for that conclusion"}, {"id": "f3", "type": "textarea", "label": "Facts that do not fit the conclusion"}, {"id": "f4", "type": "textarea", "label": "What I would say to a friend who felt this way"}, {"id": "f5", "type": "textarea", "label": "What I can say that honors the feeling without treating it as proof"}]'::jsonb, array['thinking traps', 'core CBT', 'emotion identification']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('all-or-nothing-gray-scale', 'All-or-Nothing Gray Scale', 'cbt'::resource_kind, 'A sliding scale that replaces all-or-nothing judgments with a range from 0 to 100.', 'Help a client find the middle ground in black-and-white thinking.', array['Adults', 'Teens']::text[], '15 minutes', 'Pick a judgment the client makes in extremes, such as total failure or completely ruined. Draw a line from 0 to 100, fill in what 0, 50, and 100 would actually look like, and then place the situation. Clients are often surprised by where it lands. Revisit the scale when the same all-or-nothing wording returns.', '[{"id": "f0", "type": "textarea", "label": "The all-or-nothing judgment I made"}, {"id": "f1", "type": "textarea", "label": "What a 0 would truly look like"}, {"id": "f2", "type": "textarea", "label": "What a 100 would truly look like"}, {"id": "f3", "type": "textarea", "label": "What a 50 would look like"}, {"id": "f4", "type": "textarea", "label": "Where this situation really falls"}, {"id": "f5", "type": "textarea", "label": "What would move it up a few points"}]'::jsonb, array['thinking traps', 'core CBT', 'perfectionism']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('problem-solving-ladder-planner', 'Problem-Solving Ladder Planner', 'cbt'::resource_kind, 'A six-step page that moves from a stuck problem to a chosen option, a trial, and a review.', 'Give a client a repeatable way to work through a solvable problem.', array['Adults']::text[], '30 minutes', 'Use this for problems that can actually be acted on, not for worries about things out of anyone''s hands. Spend the most time on brainstorming, where clients censor themselves early; encourage silly options too. Ask the client to pick one option and set a small trial, then review it next session rather than judging it on the spot.', '[{"id": "f0", "type": "textarea", "label": "The problem, stated in one specific sentence"}, {"id": "f1", "type": "textarea", "label": "The outcome I would like"}, {"id": "f2", "type": "textarea", "label": "Every option I can think of, even silly ones"}, {"id": "f3", "type": "textarea", "label": "The good and hard parts of my top three"}, {"id": "f4", "type": "textarea", "label": "The option I will try"}, {"id": "f5", "type": "textarea", "label": "When and how I will try it"}, {"id": "f6", "type": "textarea", "label": "What I learned from the trial"}]'::jsonb, array['skills', 'core CBT', 'behavioral']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('hands-as-thoughts-practice', 'Hands as Thoughts Practice', 'act'::resource_kind, 'A hands-on defusion exercise where thoughts held close to the face block the view and held at a distance do not.', 'Let a client feel the difference between being fused with a thought and holding it.', array['Adults']::text[], '10 minutes', 'Ask the client to cup their hands over their face and describe how easy it is to see the room and the person across from them. Then lower the hands to the lap and notice what changes. The thought is still there but they can see around it. Debrief with a real thought the client carries and ask what they could do from the lap position.', '[{"id": "f0", "type": "textarea", "label": "A thought that often takes over my attention"}, {"id": "f1", "type": "textarea", "label": "What it was like with my hands over my face"}, {"id": "f2", "type": "textarea", "label": "What it was like with my hands in my lap"}, {"id": "f3", "type": "textarea", "label": "What I could see or do differently with the thought at a distance"}, {"id": "f4", "type": "textarea", "label": "One thing I care about that I can do with the thought in my lap"}, {"id": "f5", "type": "textarea", "label": "A reminder I can use in daily life"}]'::jsonb, array['defusion', 'core ACT', 'acceptance']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('radio-doom-and-gloom-defusion', 'Radio Doom and Gloom Defusion', 'act'::resource_kind, 'A playful practice of treating a client''s gloomy mental commentary as a background radio station.', 'Help a client notice a familiar negative storyline without being run by it.', array['Adults']::text[], '15 minutes', 'Introduce the idea that the mind has a station that plays worst-case predictions, often at the worst moments. Have the client name the station, list its regular headlines, and practice carrying on with a task while it plays. Keep the tone light; the aim is not to turn it off but to stop turning up the volume.', '[{"id": "f0", "type": "textarea", "label": "The name I would give my gloomy radio station"}, {"id": "f1", "type": "textarea", "label": "Its most frequent headlines"}, {"id": "f2", "type": "textarea", "label": "When the volume goes up the most"}, {"id": "f3", "type": "textarea", "label": "What I tend to do when it is loud"}, {"id": "f4", "type": "textarea", "label": "One thing I can do while the radio plays"}, {"id": "f5", "type": "textarea", "label": "What I would be doing today if I didn''t wait for it to go quiet"}]'::jsonb, array['defusion', 'core ACT', 'thinking traps']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('values-and-goals-card-sort', 'Values and Goals Card Sort', 'act'::resource_kind, 'A sort that separates ongoing values from finishable goals so a client can tell what to aim for and what to live by.', 'Help a client see that goals can be reached while values stay a direction.', array['Adults']::text[], '25 minutes', 'Many clients fold values and goals together, then feel empty when a goal is met or missed. Have them list things they want, mark which can be checked off, and name the value behind each. Then pick a value to act on today, no matter how any goal turns out. Ask how the sort changes how they speak about their week.', '[{"id": "f0", "type": "textarea", "label": "Five things I want in my life right now"}, {"id": "f1", "type": "textarea", "label": "Which of them can be finished or checked off"}, {"id": "f2", "type": "textarea", "label": "The value behind each one"}, {"id": "f3", "type": "textarea", "label": "A value I can live out today even if a goal is stuck"}, {"id": "f4", "type": "textarea", "label": "One small action that expresses that value"}, {"id": "f5", "type": "textarea", "label": "How this changes how I judge my week"}]'::jsonb, array['values', 'core ACT', 'committed action']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('five-minute-noticing-practice', 'Five-Minute Noticing Practice', 'act'::resource_kind, 'A short present-moment practice built around five things noticed on purpose, with a log for what pulled attention away.', 'Build a daily habit of returning attention to the present.', array['Adults']::text[], 'Five minutes daily for one week', 'Show the practice in session first. The client notices five things they can see, four they can feel, three they can hear, and returns to the list when attention drifts. Slipping away is part of the practice, not a failure, so ask about the return as much as the noticing. Review the log together.', '[{"id": "f0", "type": "textarea", "label": "Where and when I practiced"}, {"id": "f1", "type": "textarea", "label": "Five things I noticed"}, {"id": "f2", "type": "textarea", "label": "What pulled my attention away"}, {"id": "f3", "type": "textarea", "label": "How I came back"}, {"id": "f4", "type": "textarea", "label": "How I felt afterward"}, {"id": "f5", "type": "textarea", "label": "When I could do this again this week"}]'::jsonb, array['mindfulness', 'core ACT', 'grounding']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('hexaflex-reflection-sheet', 'Hexaflex Reflection Sheet', 'act'::resource_kind, 'A sheet that walks a client through the six flexibility processes with one plain question each.', 'Give a client and clinician a shared picture of where flexibility is strongest and thinnest.', array['Adults']::text[], 'Full session', 'Use this as a conversation guide, not a score. Each prompt maps to one of the six processes: present moment, acceptance, defusion, self as context, values, and committed action. Let the client star the areas that feel strong and circle the ones that feel stuck. Choose one circled area for the coming weeks, based on their preference and your judgment.', '[{"id": "f0", "type": "textarea", "label": "How easy it is for me to stay in the present moment, and an example"}, {"id": "f1", "type": "textarea", "label": "What I do with uncomfortable feelings"}, {"id": "f2", "type": "textarea", "label": "How tightly I hold my thoughts"}, {"id": "f3", "type": "textarea", "label": "How I see myself beyond my thoughts and roles"}, {"id": "f4", "type": "textarea", "label": "What matters most to me right now"}, {"id": "f5", "type": "textarea", "label": "What I am doing, or could do, that fits what matters"}, {"id": "f6", "type": "textarea", "label": "The area I most want to work on next"}]'::jsonb, array['formulation', 'core ACT', 'values']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('improve-the-moment-menu', 'IMPROVE the Moment Menu', 'dbt'::resource_kind, 'A menu that turns the IMPROVE skills into a menu of choices for a hard moment.', 'Give a client a short list of ways to get through a painful moment without making it worse.', array['Adults']::text[], '25 minutes', 'Fill this out in session when the client is calm, so the choices are ready when they are not. Not every letter will fit every client; leave blanks for the ones that do not, and replace prayer with a meaning or comfort practice that suits their beliefs. Rehearse one choice aloud. Remind the client these skills help them get through a moment, not solve the problem.', '[{"id": "f0", "type": "textarea", "label": "An image that calms me or gives me strength"}, {"id": "f1", "type": "textarea", "label": "A meaning I can find in this hard time"}, {"id": "f2", "type": "textarea", "label": "A comfort or spiritual practice that fits me"}, {"id": "f3", "type": "textarea", "label": "A relaxation I can do in two minutes"}, {"id": "f4", "type": "textarea", "label": "One thing I can focus on fully right now"}, {"id": "f5", "type": "textarea", "label": "A small vacation I can take in my mind or schedule"}, {"id": "f6", "type": "textarea", "label": "An encouraging sentence I can say to myself"}, {"id": "f7", "type": "textarea", "label": "The choice I will try first"}]'::jsonb, array['distress tolerance', 'skills', 'coping skills']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('single-task-mindfulness-log', 'Single-Task Mindfulness Log', 'dbt'::resource_kind, 'A log for doing a single everyday activity with full attention and noting each time the mind wandered.', 'Build the mindfulness skill of one thing at a time.', array['Adults']::text[], 'One week', 'Ask the client to choose one routine task, such as washing dishes or brushing teeth, and give it full attention once a day. Emphasize that wandering and returning is the exercise. In review, ask what they noticed about doing one thing at a time and where multitasking shows up in the rest of their day.', '[{"id": "f0", "type": "textarea", "label": "The activity I chose"}, {"id": "f1", "type": "textarea", "label": "What I noticed with my senses"}, {"id": "f2", "type": "textarea", "label": "When my mind wandered, and where it went"}, {"id": "f3", "type": "textarea", "label": "How I brought it back"}, {"id": "f4", "type": "textarea", "label": "How I felt when I finished"}, {"id": "f5", "type": "textarea", "label": "Where I try to do many things at once"}, {"id": "f6", "type": "textarea", "label": "One place I could do just one thing this week"}]'::jsonb, array['mindfulness', 'skills', 'regulation']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('effectiveness-not-rightness-card', 'Effectiveness Not Rightness Card', 'dbt'::resource_kind, 'A pocket card for the moment a client is stuck on being right, with questions that point back to the goal.', 'Help a client choose the effective move over the satisfying one.', array['Adults']::text[], '15 minutes', 'The Effectively skill asks what will work for the goal in front of the client. Use a recent conflict where being right felt important. Let the client fill the card in session so they can carry it. Be ready for pushback; being effective does not mean giving up values or boundaries, and it is worth saying that out loud.', '[{"id": "f0", "type": "textarea", "label": "The situation where I wanted to be right"}, {"id": "f1", "type": "textarea", "label": "My goal in that situation"}, {"id": "f2", "type": "textarea", "label": "What I did that fit the goal"}, {"id": "f3", "type": "textarea", "label": "What I did that got in the way"}, {"id": "f4", "type": "textarea", "label": "What would be most effective next time"}, {"id": "f5", "type": "textarea", "label": "What I need to remember in the heat of the moment"}]'::jsonb, array['skills', 'assertiveness', 'communication']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('observe-and-describe-practice', 'Observe and Describe Practice', 'dbt'::resource_kind, 'A paired practice of observing an experience quietly and then describing it in plain facts without judgment words.', 'Teach the what-skills of observing and describing in daily life.', array['Adults', 'Teens']::text[], 'Ten minutes, three times in one week', 'Run one round in session with an object or a sound before sending it home. The client observes silently, then describes using only facts, avoiding words like good, bad, awful, or ugly. Many clients find the judgments sneak in; treat each one as something to notice, not a mistake. Compare how an emotion feels when only described.', '[{"id": "f0", "type": "textarea", "label": "What I observed, and which sense I used"}, {"id": "f1", "type": "textarea", "label": "My description using only facts"}, {"id": "f2", "type": "textarea", "label": "Judgment words that crept in"}, {"id": "f3", "type": "textarea", "label": "How I would say it without the judgments"}, {"id": "f4", "type": "textarea", "label": "A feeling I noticed and described the same way"}, {"id": "f5", "type": "textarea", "label": "What I learned from describing"}]'::jsonb, array['mindfulness', 'skills', 'emotion identification']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('skills-reminder-wallet-cards', 'Skills Reminder Wallet Cards', 'dbt'::resource_kind, 'A set of small cards a client fills with their own top skills, to carry where they will be needed.', 'Make favorite coping skills easy to find in the moment.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client choose three to five skills they have already tried and write each in their own words on a card, with the steps in short form. Laminate or photograph the cards if possible. Revisit after a week and swap out any that were not used. The client picks the skills; you check that the set covers a range of intensities.', '[{"id": "f0", "type": "textarea", "label": "The skill I want on card one"}, {"id": "f1", "type": "textarea", "label": "Its steps in my own words"}, {"id": "f2", "type": "textarea", "label": "The skill for card two and its steps"}, {"id": "f3", "type": "textarea", "label": "The skill for card three and its steps"}, {"id": "f4", "type": "textarea", "label": "Where I will keep the cards"}, {"id": "f5", "type": "textarea", "label": "The situation I most want them for"}, {"id": "f6", "type": "textarea", "label": "A time I will review the cards"}]'::jsonb, array['skills', 'coping skills', 'distress tolerance']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('reunion-ritual-plan', 'Reunion Ritual Plan', 'couples'::resource_kind, 'A plan for the first twenty minutes after partners reunite each day, with each partner naming what helps them land.', 'Help partners reconnect in the daily handoff from work to home.', array['Couples']::text[], '30 minutes', 'Partners are often tired and talk past each other in the first minutes at home. Each partner describes what helps them land, such as a hug, quiet, a snack, or a few minutes alone. Then they write one shared ritual. Check that both preferences are heard, not only the louder one. Revisit in a week and adjust.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me land after the day"}, {"id": "f1", "type": "textarea", "label": "Partner B: what helps me land after the day"}, {"id": "f2", "type": "textarea", "label": "What we each tend to do in the first twenty minutes now"}, {"id": "f3", "type": "textarea", "label": "What we each wish the other would do or not do"}, {"id": "f4", "type": "textarea", "label": "Our shared reunion ritual, step by step"}, {"id": "f5", "type": "textarea", "label": "What we will do on days one of us needs more space"}, {"id": "f6", "type": "textarea", "label": "When we will check how it is going"}]'::jsonb, array['connection', 'Gottman', 'routines']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('unspoken-rules-inventory', 'Unspoken Rules Inventory', 'couples'::resource_kind, 'A list where each partner writes the rules they assumed the relationship runs on, then compares and negotiates them.', 'Bring hidden expectations into the open so partners can choose them together.', array['Couples']::text[], 'Full session', 'Partners complete the first half separately, then share. Common unspoken rules involve money, time, who initiates, and what counts as respect. Treat differences as information about each person''s history, not as faults. Each partner owns their rules by saying I assumed rather than you should. Help them keep, change, or drop each rule together.', '[{"id": "f0", "type": "textarea", "label": "Partner A: rules I assumed we followed"}, {"id": "f1", "type": "textarea", "label": "Partner B: rules I assumed we followed"}, {"id": "f2", "type": "textarea", "label": "Rules we both assumed"}, {"id": "f3", "type": "textarea", "label": "Rules only one of us assumed"}, {"id": "f4", "type": "textarea", "label": "Where each of our rules came from"}, {"id": "f5", "type": "textarea", "label": "Rules we choose to keep"}, {"id": "f6", "type": "textarea", "label": "Rules we want to change, and a first step"}]'::jsonb, array['communication', 'relationship issues', 'conflict']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('our-story-timeline', 'Our Story Timeline', 'couples'::resource_kind, 'A shared timeline of key moments, from first meeting to now, with what each partner remembers and values about them.', 'Rebuild shared meaning by revisiting the story of the relationship together.', array['Couples']::text[], 'Full session', 'Have partners draw a line and mark five to eight moments, then each write what they remember in their own words. Differences in memory can be interesting rather than a problem. Steer toward moments of choosing each other and getting through something. If a painful moment comes up, name it briefly and decide together whether it belongs here.', '[{"id": "f0", "type": "textarea", "label": "Partner A: our first meeting as I remember it"}, {"id": "f1", "type": "textarea", "label": "Partner B: our first meeting as I remember it"}, {"id": "f2", "type": "textarea", "label": "A time we got through something hard together"}, {"id": "f3", "type": "textarea", "label": "A moment I felt proud of us"}, {"id": "f4", "type": "textarea", "label": "A moment I felt closest to you"}, {"id": "f5", "type": "textarea", "label": "What I admire about us as a pair"}, {"id": "f6", "type": "textarea", "label": "A chapter we want to write next"}]'::jsonb, array['connection', 'Gottman', 'couples']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('affection-preferences-menu', 'Affection Preferences Menu', 'couples'::resource_kind, 'A menu where each partner lists the kinds of affection they like, how often, and when, to compare side by side.', 'Help partners talk about affection preferences without blame.', array['Couples']::text[], '30 minutes', 'Each partner marks which forms of affection they enjoy, such as touch, words, notes, time, or small acts, and when they like them. Differences are common and are not a measure of love. Encourage each partner to describe what they enjoy rather than criticize what is missing. Keep the focus on non-sexual affection unless the couple wants to widen it.', '[{"id": "f0", "type": "textarea", "label": "Partner A: kinds of affection I enjoy most"}, {"id": "f1", "type": "textarea", "label": "Partner B: kinds of affection I enjoy most"}, {"id": "f2", "type": "textarea", "label": "Times of day or moments I like affection"}, {"id": "f3", "type": "textarea", "label": "Times I would rather have space"}, {"id": "f4", "type": "textarea", "label": "One kind of affection I would like to try more"}, {"id": "f5", "type": "textarea", "label": "One kind I would like us to ask about first"}, {"id": "f6", "type": "textarea", "label": "How we will tell each other yes, no, or not now"}]'::jsonb, array['connection', 'communication', 'couples']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('shared-calendar-conversation-sheet', 'Shared Calendar Conversation Sheet', 'couples'::resource_kind, 'A weekly sheet where partners place work, chores, time together, and time apart on one page before the week starts.', 'Reduce hidden scheduling friction by planning the week as a team.', array['Couples']::text[], '20 minutes weekly', 'Partners sit with both calendars and walk through the week. Each names must-do items first, then what they hope for. Look at whether one partner carries more of the planning, and invite them to share it. Always put at least one block of time together and one of time alone on the page.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my must-do items this week"}, {"id": "f1", "type": "textarea", "label": "Partner B: my must-do items this week"}, {"id": "f2", "type": "textarea", "label": "Chores and errands we need to split"}, {"id": "f3", "type": "textarea", "label": "Time together we are protecting"}, {"id": "f4", "type": "textarea", "label": "Time apart each of us wants"}, {"id": "f5", "type": "textarea", "label": "A pressure point in the week and a plan for it"}, {"id": "f6", "type": "textarea", "label": "What we will review next week"}]'::jsonb, array['routines', 'communication', 'relationship issues']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('glitter-jar-calm-craft', 'Glitter Jar Calm Craft', 'kids'::resource_kind, 'A child makes a glitter jar and watches the swirl settle while practicing slow breathing.', 'Give a child a hands-on picture of big feelings settling.', array['Children']::text[], '25 minutes', 'The child and parent fill a jar with water, clear glue, and glitter, then shake it. While it settles, the child breathes slowly and names how their body feels. The parent joins in and later uses the jar in calm moments, offered as a choice, never as a punishment. Keep the jar sealed and supervised. Remind the parent of reporting duties if the child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "What I put in my jar and what it looked like"}, {"id": "f1", "type": "textarea", "label": "What the swirl made me think of"}, {"id": "f2", "type": "textarea", "label": "How my body felt while the glitter settled"}, {"id": "f3", "type": "textarea", "label": "A feeling that sometimes swirls inside me"}, {"id": "f4", "type": "textarea", "label": "What helps my feelings settle"}, {"id": "f5", "type": "textarea", "label": "Where we will keep the jar at home"}]'::jsonb, array['children', 'play', 'regulation']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('my-calm-corner-design', 'My Calm Corner Design', 'kids'::resource_kind, 'A child draws and plans a cozy corner at home, and the parent helps set it up and agrees when it is used.', 'Create a child-chosen place for calming down that is never used as a punishment.', array['Children']::text[], '30 minutes', 'Have the child draw their ideal calm spot, then choose items such as a pillow, a book, or a stuffed animal. The parent builds it with them at home and practices going there together first. The corner is an invitation, not a consequence. Remind parents about their reporting duties if a child says anything that concerns you about safety.', '[{"id": "f0", "type": "textarea", "label": "Draw or describe my calm corner"}, {"id": "f1", "type": "textarea", "label": "Soft things I want in it"}, {"id": "f2", "type": "textarea", "label": "Things to do there when I feel upset"}, {"id": "f3", "type": "textarea", "label": "How I will know I want to go there"}, {"id": "f4", "type": "textarea", "label": "Who can sit with me if I ask"}, {"id": "f5", "type": "textarea", "label": "What my parent will say when I go there"}]'::jsonb, array['children', 'regulation', 'routines']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('pocket-comfort-stone', 'Pocket Comfort Stone', 'kids'::resource_kind, 'A child paints or chooses a smooth stone to carry as a reminder of a calming skill.', 'Give a child a small, portable reminder of something that helps them feel safe.', array['Children']::text[], '20 minutes', 'The child chooses a stone, decorates it, and picks a calming skill it stands for, such as slow breathing or squeezing it. The parent practices the skill with the child and agrees on a short phrase to say. Keep it light; the stone is a cue and a comfort. Parents should know the stone is for comfort, and you are available to talk if the child discloses something that worries them.', '[{"id": "f0", "type": "textarea", "label": "What I drew or painted on my stone"}, {"id": "f1", "type": "textarea", "label": "The calm skill my stone reminds me of"}, {"id": "f2", "type": "textarea", "label": "A time I might hold it"}, {"id": "f3", "type": "textarea", "label": "What I can say to myself when I hold it"}, {"id": "f4", "type": "textarea", "label": "Who I can tell when I need help"}, {"id": "f5", "type": "textarea", "label": "Where I will keep it"}]'::jsonb, array['children', 'play', 'coping skills']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('feelings-pizza-drawing', 'Feelings Pizza Drawing', 'kids'::resource_kind, 'A child draws a pizza and divides it into slices for each feeling they had that day, making bigger slices for bigger feelings.', 'Help a child see that many feelings can sit together in one day.', array['Children']::text[], '20 minutes', 'The child draws a circle and cuts it into slices, one for each feeling of the day, sizing slices to match how much they felt it. The parent takes a turn with their own pizza so the child sees feelings are normal for adults too. Listen without fixing. If the child mentions harm or fear at home or elsewhere, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "The feelings in my pizza today"}, {"id": "f1", "type": "textarea", "label": "Which slice is the biggest"}, {"id": "f2", "type": "textarea", "label": "What happened to make that feeling"}, {"id": "f3", "type": "textarea", "label": "A small slice that is still important"}, {"id": "f4", "type": "textarea", "label": "What my body felt like with the big slice"}, {"id": "f5", "type": "textarea", "label": "What I want a grown-up to know about my day"}]'::jsonb, array['children', 'emotion identification', 'play']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('kind-words-postcard', 'Kind Words Postcard', 'kids'::resource_kind, 'A child writes and decorates a postcard to a future self with kind words, then the parent mails or posts it.', 'Help a child practice speaking kindly to themselves.', array['Children']::text[], '25 minutes', 'The child makes a postcard to themselves with a kind message and a picture of something they like about themselves. The parent adds a note of their own, and later reads it with them. The aim is practicing a kind inner voice, not praise for performing. If a child''s drawings or words raise safety concerns, use your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "What I drew on my postcard"}, {"id": "f1", "type": "textarea", "label": "Something I like about myself"}, {"id": "f2", "type": "textarea", "label": "Something I did that was brave"}, {"id": "f3", "type": "textarea", "label": "Kind words I want to hear when I feel down"}, {"id": "f4", "type": "textarea", "label": "What a good friend would say to me"}, {"id": "f5", "type": "textarea", "label": "When I will read my postcard"}]'::jsonb, array['children', 'self-compassion', 'play']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('feelings-pictionary-relay', 'Feelings Pictionary Relay', 'game'::resource_kind, 'A team drawing game where players sketch feelings and situations for teammates to guess.', 'Build feelings vocabulary through quick drawing and guessing.', array['Children', 'Teens', 'Groups']::text[], '30 minutes', 'Split into two teams. Each round, one player draws a feeling from a card while teammates guess within a minute, and no letters or words are allowed. After each round, ask what clues told the team the feeling. End with a debrief about which feelings were easy and hard to draw and how people show them. Keep it silly and give every player a turn.', '[{"id": "f0", "type": "textarea", "label": "The feeling I drew or guessed"}, {"id": "f1", "type": "textarea", "label": "The clues that helped"}, {"id": "f2", "type": "textarea", "label": "A feeling that was hard to draw"}, {"id": "f3", "type": "textarea", "label": "A time I felt it"}, {"id": "f4", "type": "textarea", "label": "How my body showed it"}, {"id": "f5", "type": "textarea", "label": "What I learned about showing feelings to others"}]'::jsonb, array['emotion identification', 'play', 'group']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('skill-tic-tac-toe', 'Skill Tic-Tac-Toe', 'game'::resource_kind, 'A tic-tac-toe board where each square holds a coping skill that the player must describe before claiming it.', 'Make rehearsing skills a playful, turn-taking activity.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Draw a three-by-three board and write a coping skill in each square. On their turn, a player describes when and how they would use the skill to claim the square. Opponents may ask one question. The debrief covers which skills players claim often and which they avoid. Clinician judgment guides how deep each answer goes.', '[{"id": "f0", "type": "textarea", "label": "The skill in the square I claimed"}, {"id": "f1", "type": "textarea", "label": "When I would use it"}, {"id": "f2", "type": "textarea", "label": "What would make it hard to use"}, {"id": "f3", "type": "textarea", "label": "A skill I avoided and why"}, {"id": "f4", "type": "textarea", "label": "A skill someone else described that I want to try"}, {"id": "f5", "type": "textarea", "label": "The skill I will practice this week"}]'::jsonb, array['skills', 'coping skills', 'play']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('strengths-hot-potato', 'Strengths Hot Potato', 'game'::resource_kind, 'Players pass an object around the circle and name a strength about another player when the music stops.', 'Help players hear and give specific strengths in a group.', array['Teens', 'Groups']::text[], '20 minutes', 'Pass a soft object while music plays. When it stops, the holder names one specific strength of the person to their left, with an example. If the group is new, offer sentence starters. Pause for anyone who struggles to accept a compliment. Debrief what it was like to give and to receive. Make sure everyone receives at least one strength.', '[{"id": "f0", "type": "textarea", "label": "A strength someone named in me"}, {"id": "f1", "type": "textarea", "label": "How it felt to hear it"}, {"id": "f2", "type": "textarea", "label": "A strength I named in someone else"}, {"id": "f3", "type": "textarea", "label": "What made it easy or hard to say"}, {"id": "f4", "type": "textarea", "label": "A strength I rarely give myself credit for"}, {"id": "f5", "type": "textarea", "label": "Who in my life I could tell about a strength I see in them"}]'::jsonb, array['group', 'connection', 'self-esteem']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('story-chain-coping', 'Story Chain Coping', 'game'::resource_kind, 'A group builds a story one sentence at a time about a character facing a problem, adding a coping skill at each turn.', 'Practice generating coping ideas through shared storytelling.', array['Children', 'Teens', 'Groups']::text[], '25 minutes', 'Start the story with a character facing a small problem. Each player adds one sentence, and every second turn must include a coping skill the character tries. The story can wander. In the debrief, ask which skills the character used, which the group would try, and how the character felt at the end. Keep the problem mild and let the group steer.', '[{"id": "f0", "type": "textarea", "label": "The problem our character faced"}, {"id": "f1", "type": "textarea", "label": "The skills the character tried"}, {"id": "f2", "type": "textarea", "label": "Which one worked best for the character"}, {"id": "f3", "type": "textarea", "label": "A skill I would try myself"}, {"id": "f4", "type": "textarea", "label": "How the story ended"}, {"id": "f5", "type": "textarea", "label": "What I want to remember from the story"}]'::jsonb, array['coping skills', 'play', 'group']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('mindful-sound-bingo', 'Mindful Sound Bingo', 'game'::resource_kind, 'A bingo card of everyday sounds that players mark as they listen quietly for a few minutes.', 'Practice mindful listening with a playful goal.', array['Children', 'Teens', 'Groups']::text[], '15 minutes', 'Hand out cards with sounds such as a door closing, a bird, footsteps, or a hum. Everyone sits quietly and marks a square when they hear that sound. The first to complete a line wins, but everyone gets a turn to share. Debrief what they noticed once they were listening on purpose, and how attention wandered and returned.', '[{"id": "f0", "type": "textarea", "label": "Sounds I marked on my card"}, {"id": "f1", "type": "textarea", "label": "A sound I heard that was not on the card"}, {"id": "f2", "type": "textarea", "label": "What my mind did while I listened"}, {"id": "f3", "type": "textarea", "label": "How I felt in my body when it was quiet"}, {"id": "f4", "type": "textarea", "label": "A place I could listen mindfully this week"}, {"id": "f5", "type": "textarea", "label": "What I noticed about my attention"}]'::jsonb, array['mindfulness', 'play', 'group']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('dropping-anchor-practice-1005a', 'Steady in the Storm Anchor Script', 'act'::resource_kind, 'A short ACT exercise for steadying the body and attention in the middle of strong feelings, with a client-built script.', 'Give a client a brief way to feel their feet, name what is here, and re-engage with the room.', array['Adults', 'Teens']::text[], '15 minutes', 'Walk the client through the three steps in session first: notice thoughts and feelings, connect with the body by pushing feet into the floor, then notice the room. The aim is steadiness, not making feelings leave. Keep eyes open if closing them feels unsafe, and never ask for any account of past events. Let the client edit the wording until it sounds like them.', '[{"id": "f0", "type": "textarea", "label": "The feelings and thoughts I notice are..."}, {"id": "f1", "type": "textarea", "label": "One way I can feel my body in the chair or on the floor is..."}, {"id": "f2", "type": "textarea", "label": "Five things I can see around me right now are..."}, {"id": "f3", "type": "textarea", "label": "A sound I can hear that tells me where I am today is..."}, {"id": "f4", "type": "textarea", "label": "The one thing I want to do next, once I feel steadier, is..."}]'::jsonb, array['PTSD and trauma', 'grounding', 'defusion']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('nighttime-settling-plan-1005a', 'Nighttime Settling Plan', 'worksheet'::resource_kind, 'A client''s written plan for the hour before bed that builds in safety cues, comfort, and a way back if they wake.', 'Help a client create a predictable, safe-feeling evening routine and a plan for waking at night.', array['Adults', 'Teens']::text[], '20 minutes, then one week of use', 'Evenings can be a hard stretch when the day goes quiet. Build the plan together in session and keep it simple and stabilizing: lights, locks, comfort items, a calming activity, and a short grounding step to use on waking. Adjust to what the client reports and review it the following week. Nothing here asks the client to recall or write about past events.', '[{"id": "f0", "type": "textarea", "label": "Things that help my space feel safe at night are..."}, {"id": "f1", "type": "textarea", "label": "Three calming things I could do in the last hour before bed are..."}, {"id": "f2", "type": "textarea", "label": "A comfort item or sensation I want close by is..."}, {"id": "f3", "type": "textarea", "label": "If I wake up unsettled, the first thing I will do is..."}, {"id": "f4", "type": "textarea", "label": "A person I could reach out to the next day is..."}, {"id": "f5", "type": "textarea", "label": "What I noticed after trying the plan was..."}]'::jsonb, array['PTSD and trauma', 'sleep', 'safety']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('safe-people-hand-map-1005a', 'Safe People Hand Map', 'kids'::resource_kind, 'A child traces their hand and writes one trusted person on each finger, so they know who to go to.', 'Help a child name the trusted people they can turn to when they feel scared or upset.', array['Children']::text[], '20 minutes', 'The child traces a hand, then names a trusted person for each finger and what that person does to help. The parent joins in and listens without quizzing, and keeps the tone warm and unhurried. If the child discloses anything, follow your reporting duties and your clinical judgment. Display the map where the child can see it at home.', '[{"id": "f0", "type": "textarea", "label": "The person on my thumb is..."}, {"id": "f1", "type": "textarea", "label": "The person on my pointer finger is..."}, {"id": "f2", "type": "textarea", "label": "The person on my middle finger is..."}, {"id": "f3", "type": "textarea", "label": "The person on my ring finger is..."}, {"id": "f4", "type": "textarea", "label": "The person on my pinky is..."}, {"id": "f5", "type": "textarea", "label": "When I feel scared, the first person I will go to is..."}]'::jsonb, array['PTSD and trauma', 'children', 'safety']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('grounding-scavenger-round-1005a', 'Grounding Scavenger Round', 'game'::resource_kind, 'A turn-taking game in which players find items in the room by sense, color, or texture to practice settling attention.', 'Let a client or group practice grounding in a playful, low-pressure way before they need it.', array['Teens', 'Adults', 'Groups']::text[], '15 minutes', 'Rules: players take turns drawing a prompt card such as find something blue, soft, or round, and everyone has 60 seconds to find one. Players name the item aloud and what they notice about it. Debrief by asking which prompts felt steadying and which felt like too much. Keep it optional, let anyone pass, and avoid any discussion of past events.', '[{"id": "f0", "type": "textarea", "label": "The prompts that helped me feel here and now were..."}, {"id": "f1", "type": "textarea", "label": "A sense I find easiest to use for grounding is..."}, {"id": "f2", "type": "textarea", "label": "A prompt I would change or skip is..."}, {"id": "f3", "type": "textarea", "label": "One place outside this room I could use this game is..."}, {"id": "f4", "type": "textarea", "label": "What I noticed in my body during the game was..."}]'::jsonb, array['PTSD and trauma', 'grounding', 'game']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('hard-day-pacing-agreement-1005a', 'Hard Day Pacing Agreement', 'couples'::resource_kind, 'Partners write what each will do and avoid on a hard day, so support stays steady and unpressured.', 'Help partners agree on how one partner signals a hard day and how the other responds.', array['Couples']::text[], '30 minutes', 'Partner A, the one having the hard day, names early signs, what helps, and what to hold off on. Partner B writes how they will offer support and how they will care for themselves. Keep the conversation on pacing and safety, not on details of the past, and let each partner set limits. Revisit the agreement after a few weeks.', '[{"id": "f0", "type": "textarea", "label": "Partner A: signs that today is a hard day are..."}, {"id": "f1", "type": "textarea", "label": "Partner A: things that help me on a hard day are..."}, {"id": "f2", "type": "textarea", "label": "Partner A: things I would like you to hold off on are..."}, {"id": "f3", "type": "textarea", "label": "Partner B: how I will check in without pressing is..."}, {"id": "f4", "type": "textarea", "label": "Partner B: how I will take care of myself on those days is..."}, {"id": "f5", "type": "textarea", "label": "Together: the words or sign we will use to start this plan are..."}]'::jsonb, array['PTSD and trauma', 'couples', 'pacing']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('cope-ahead-rehearsal-plan-1005a', 'Cope Ahead Rehearsal Plan', 'dbt'::resource_kind, 'A DBT-style plan that has the client picture a worrying situation and rehearse the skills they will use there.', 'Help a client get ready for a difficult upcoming event by rehearsing specific skills in advance.', array['Adults', 'Teens']::text[], '25 minutes', 'Pick one upcoming situation that brings anxiety and walk through it with the client step by step, naming the skills they will use at each point. The client imagines themselves coping, not perfect. Rehearse out loud in session if you can. Keep the plan short enough to read on a phone, and adjust it after the event together.', '[{"id": "f0", "type": "textarea", "label": "The situation I am getting ready for is..."}, {"id": "f1", "type": "textarea", "label": "The moment I expect to feel the most anxious is..."}, {"id": "f2", "type": "textarea", "label": "Skills I could use at that moment are..."}, {"id": "f3", "type": "textarea", "label": "What I will say to myself while it is happening is..."}, {"id": "f4", "type": "textarea", "label": "The first small step I will take afterward is..."}]'::jsonb, array['anxiety', 'cope ahead', 'distress tolerance']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('partner-reassurance-reset-plan-1005a', 'Partner Reassurance Reset Plan', 'couples'::resource_kind, 'Partners agree how to respond when one asks for repeated reassurance, with a kind script for both sides.', 'Help partners replace repeated reassurance loops with a response both of them can live with.', array['Couples']::text[], '30 minutes', 'The anxious partner names what they tend to ask and what it gives them for a moment. The other partner names how those moments feel on their side. Together they write one warm response and one thing the asking partner can try first. Frame it as a team plan, avoid blame, and note that some reassurance is normal and fine.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the question I find myself asking again is..."}, {"id": "f1", "type": "textarea", "label": "Partner A: what I feel in my body just before I ask is..."}, {"id": "f2", "type": "textarea", "label": "Partner B: how I feel when I am asked again is..."}, {"id": "f3", "type": "textarea", "label": "Partner B: a kind, short thing I can say is..."}, {"id": "f4", "type": "textarea", "label": "Partner A: something I can try before asking is..."}, {"id": "f5", "type": "textarea", "label": "Together: how we will check how the plan is going is..."}]'::jsonb, array['anxiety', 'couples', 'reassurance']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('anxiety-myth-or-fact-showdown-1005a', 'Anxiety Myth or Fact Showdown', 'game'::resource_kind, 'A two-team quiz game about common beliefs on anxiety, with cards the group sorts into myth, fact, and it depends.', 'Open up a group conversation about what people believe about anxiety and how those beliefs shape coping.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Rules: split the group into two teams, read a statement card, and let each team vote myth, fact, or it depends, then explain why. Award a point for a reasoned answer, not just a right one. Debrief on which beliefs people hold personally and which they would like to test. Keep it light and let anyone pass.', '[{"id": "f0", "type": "textarea", "label": "A belief about anxiety I heard growing up was..."}, {"id": "f1", "type": "textarea", "label": "A card that surprised me was..."}, {"id": "f2", "type": "textarea", "label": "A belief I would like to test in my own life is..."}, {"id": "f3", "type": "textarea", "label": "Something I would tell a friend who believed a myth is..."}, {"id": "f4", "type": "textarea", "label": "What I want to remember from the game is..."}]'::jsonb, array['anxiety', 'psychoeducation', 'game']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('calm-corner-menu-1005a', 'Calm Corner Menu', 'worksheet'::resource_kind, 'A client designs a menu of calming options for sight, sound, touch, and movement that they can use at home or school.', 'Help a client build a personal menu of calming choices they can reach for before anxiety peaks.', array['Teens', 'Adults', 'Children']::text[], '20 minutes', 'Work through each sense and movement option and let the client pick what actually appeals, not what they think they should choose. Have them try two or three in session and rate how each felt. For younger clients, a parent can help set up a physical corner. Revisit the menu and swap out what no longer helps.', '[{"id": "f0", "type": "textarea", "label": "Something calming to look at is..."}, {"id": "f1", "type": "textarea", "label": "A sound or music that settles me is..."}, {"id": "f2", "type": "textarea", "label": "A texture or object that feels good to hold is..."}, {"id": "f3", "type": "textarea", "label": "A way of moving that releases tension is..."}, {"id": "f4", "type": "textarea", "label": "A place at home or school I could use as a calm spot is..."}, {"id": "f5", "type": "textarea", "label": "The option I will try first this week is..."}]'::jsonb, array['anxiety', 'calming', 'self-soothing']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('cloud-weather-feelings-mobile-1005a', 'Cloud Weather Feelings Mobile', 'kids'::resource_kind, 'A child makes a hanging mobile of feelings as weather and talks about how storms pass and the sky changes.', 'Help a child see anxious feelings as changing weather that comes and goes.', array['Children']::text[], '30 minutes', 'The child cuts or draws clouds, sun, rain, and wind, writes a feeling on each, and hangs them from a hanger. The parent helps tie the pieces and asks what the weather is today, accepting whatever the child says. Hang the mobile in their room and let them move pieces when feelings change. Keep the conversation curious and unhurried.', '[{"id": "f0", "type": "textarea", "label": "Today my feeling weather is..."}, {"id": "f1", "type": "textarea", "label": "The weather that feels biggest to me is..."}, {"id": "f2", "type": "textarea", "label": "A cloud that shows how my worries look is..."}, {"id": "f3", "type": "textarea", "label": "What helps a storm feel smaller is..."}, {"id": "f4", "type": "textarea", "label": "A sunny spot in my day is..."}]'::jsonb, array['anxiety', 'children', 'feelings']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('making-room-for-heavy-feelings-1005a', 'Making Room for Heavy Feelings Practice', 'act'::resource_kind, 'An ACT practice in which a client notices where heaviness sits in the body and makes room for it while choosing a small action.', 'Help a client carry low mood while still taking one small step that matters to them.', array['Adults', 'Teens']::text[], '20 minutes', 'Guide the client to notice where the heaviness sits, give it a shape or color, and breathe around it rather than away from it. The point is room, not removal. Then choose one small action tied to a value. Go slowly, and respect a client who finds the body focus hard. If hopelessness or thoughts of self-harm come up, talk about it in session.', '[{"id": "f0", "type": "textarea", "label": "Where I feel heaviness in my body is..."}, {"id": "f1", "type": "textarea", "label": "If it had a shape, color, or weight, it would be..."}, {"id": "f2", "type": "textarea", "label": "What it is like to make a little room around it is..."}, {"id": "f3", "type": "textarea", "label": "Something that matters to me, even on a heavy day, is..."}, {"id": "f4", "type": "textarea", "label": "One small step I can take with the heaviness along is..."}, {"id": "f5", "type": "textarea", "label": "If things feel unsafe, I can call or text 988 or tell a trusted person. The first person I would tell is..."}]'::jsonb, array['depression', 'acceptance', 'values']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('accumulating-positive-emotions-planner-1005a', 'Accumulating Positive Emotions Planner', 'dbt'::resource_kind, 'A DBT-style weekly plan that adds short-term pleasant events and one long-term value-based step.', 'Help a client build more small pleasant moments into the week, and one step toward something bigger.', array['Adults', 'Teens']::text[], '25 minutes', 'This is the accumulate positive emotions skill in planner form. Have the client pick a few pleasant events they can do this week, mindful of what feels doable at their current energy. Add one longer-term step. Review it next session, and be curious about what got in the way rather than what was missed.', '[{"id": "f0", "type": "textarea", "label": "Pleasant things I could do in the next few days are..."}, {"id": "f1", "type": "textarea", "label": "The ones that feel doable at my energy level are..."}, {"id": "f2", "type": "textarea", "label": "I will do them at these times..."}, {"id": "f3", "type": "textarea", "label": "One longer-term thing I care about is..."}, {"id": "f4", "type": "textarea", "label": "One small step toward it this week is..."}, {"id": "f5", "type": "textarea", "label": "What I noticed after trying them was..."}]'::jsonb, array['depression', 'DBT skills', 'positive emotions']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('connection-without-pressure-plan-1005a', 'Connection Without Pressure Plan', 'couples'::resource_kind, 'Partners plan small, low-demand ways to stay connected when one partner has low mood and little energy.', 'Help partners find ways to be close that do not depend on the low-mood partner''s energy.', array['Couples']::text[], '30 minutes', 'The partner with low mood names what feels manageable and what feels like too much. The other partner names what connection they miss and what they can offer without asking for much back. Together they choose two or three tiny rituals. Keep it free of blame, and check in on what is working after a week.', '[{"id": "f0", "type": "textarea", "label": "Partner A: connection that feels manageable right now is..."}, {"id": "f1", "type": "textarea", "label": "Partner A: what feels like too much is..."}, {"id": "f2", "type": "textarea", "label": "Partner B: what I miss and would like more of is..."}, {"id": "f3", "type": "textarea", "label": "Partner B: something I can offer with nothing needed back is..."}, {"id": "f4", "type": "textarea", "label": "Together: two small rituals we will try are..."}, {"id": "f5", "type": "textarea", "label": "Together: when we will check in about it is..."}]'::jsonb, array['depression', 'couples', 'connection']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('mood-weather-chart-craft-1005a', 'Mood Weather Chart Craft', 'kids'::resource_kind, 'A child builds a weekly weather-style mood chart with stickers and chooses one kind thing to do on gray days.', 'Help a child notice and name mood changes and have a plan for lower days.', array['Children']::text[], '30 minutes', 'The child decorates a weekly chart and picks weather stickers to show how each day felt. The parent fills in alongside, models naming their own mood, and does not judge any day. Together choose one kind thing to do on gray days. Look at the chart weekly and share patterns with the clinician.', '[{"id": "f0", "type": "textarea", "label": "The weather of my day today is..."}, {"id": "f1", "type": "textarea", "label": "On my best day this week I felt..."}, {"id": "f2", "type": "textarea", "label": "On my grayest day I felt..."}, {"id": "f3", "type": "textarea", "label": "One kind thing I can do on a gray day is..."}, {"id": "f4", "type": "textarea", "label": "A grown-up I can tell when I have a gray day is..."}]'::jsonb, array['depression', 'children', 'mood tracking']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('self-critical-voice-rewrite-1005a', 'Self-Critical Voice Rewrite', 'cbt'::resource_kind, 'A CBT sheet where a client catches a harsh inner statement, tests it, and rewrites it in a fairer voice.', 'Help a client notice self-critical thoughts and practice a more balanced response.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to pick one recent harsh thought, rate how much they believe it, and look at evidence on both sides. Then draft a fairer sentence they could say to a friend. The goal is balance, not forced positivity. Re-rate the belief at the end and watch for the client dismissing the new statement as untrue.', '[{"id": "f0", "type": "textarea", "label": "The harsh thing my mind said was..."}, {"id": "f1", "type": "textarea", "label": "How much I believed it, 0 to 100, was..."}, {"id": "f2", "type": "textarea", "label": "Things that fit with that thought are..."}, {"id": "f3", "type": "textarea", "label": "Things that do not fit are..."}, {"id": "f4", "type": "textarea", "label": "What I would say to a friend who thought this is..."}, {"id": "f5", "type": "textarea", "label": "How much I believe the first thought now is..."}]'::jsonb, array['depression', 'thought record', 'self-criticism']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('task-switch-card-game-1005a', 'Task Switch Card Game', 'game'::resource_kind, 'A card game in which players practice stopping one activity and starting another, with a reset step in between.', 'Give a client playful practice at the pause, reset, and start steps of switching between tasks.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Rules: players take turns drawing a task card, work on it for one minute, then draw a switch card with the next task. Between rounds, they say aloud the three reset steps: pause, name what is next, take the first step. Debrief on which switches felt hardest and what helped. Keep the pace friendly and not competitive.', '[{"id": "f0", "type": "textarea", "label": "The switches that felt easiest were..."}, {"id": "f1", "type": "textarea", "label": "The switches that felt hardest were..."}, {"id": "f2", "type": "textarea", "label": "The reset step that helped me most was..."}, {"id": "f3", "type": "textarea", "label": "A real-life switch I would like to practice is..."}, {"id": "f4", "type": "textarea", "label": "Something I will try this week is..."}]'::jsonb, array['ADHD', 'transitions', 'game']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('next-action-cue-cards-1005a', 'Next Action Cue Cards', 'cbt'::resource_kind, 'A set of client-made cards that name the very next physical action for tasks that tend to stall.', 'Help a client turn vague tasks into one visible, concrete next action they can start.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose three tasks that keep stalling and write each on a card, with the very next physical action on the back, small enough to start in two minutes. Have the client test one in session. Notice what makes a card too vague, and refine it together. Keep the cards where the task happens.', '[{"id": "f0", "type": "textarea", "label": "A task I keep putting off is..."}, {"id": "f1", "type": "textarea", "label": "The very next physical action on it is..."}, {"id": "f2", "type": "textarea", "label": "How long that action would take me is..."}, {"id": "f3", "type": "textarea", "label": "What might get in the way is..."}, {"id": "f4", "type": "textarea", "label": "What I will do if I get stuck is..."}, {"id": "f5", "type": "textarea", "label": "How it went when I tried the card was..."}]'::jsonb, array['ADHD', 'task initiation', 'cue cards']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('boredom-willingness-practice-1005a', 'Boredom Willingness Practice', 'act'::resource_kind, 'An ACT practice in which a client notices the pull away from a dull task and practices staying with it for a short stretch.', 'Help a client notice restlessness and choose to stay with a task that matters to them.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick a task that matters but is dull. The client sets a short timer, notices the urge to switch, names it, and keeps going, then writes what the urge did. The goal is willingness, not force or perfect focus. Pair it with a value so the stay has a reason, and make the stretch short enough to succeed.', '[{"id": "f0", "type": "textarea", "label": "A task that matters to me but feels dull is..."}, {"id": "f1", "type": "textarea", "label": "The pull away from it feels like..."}, {"id": "f2", "type": "textarea", "label": "Why it matters to me is..."}, {"id": "f3", "type": "textarea", "label": "The length of time I will stay with it is..."}, {"id": "f4", "type": "textarea", "label": "What the urge did while I kept going was..."}, {"id": "f5", "type": "textarea", "label": "What I would like to try next time is..."}]'::jsonb, array['ADHD', 'willingness', 'values']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('weekly-reset-checklist-builder-1005a', 'Weekly Reset Checklist Builder', 'worksheet'::resource_kind, 'A client builds a short weekly reset checklist covering space, calendar, and tasks, and picks a regular time to do it.', 'Help a client set up a brief weekly routine that keeps small things from piling up.', array['Adults', 'Teens']::text[], '25 minutes', 'Build the checklist with the client from what actually slips: papers, calendar, messages, laundry. Keep it to five or six items they can finish in about twenty minutes, and fix a regular day and time with a cue. Expect to revise it after a week or two, and treat a missed reset as information to adjust the plan.', '[{"id": "f0", "type": "textarea", "label": "Things that pile up for me are..."}, {"id": "f1", "type": "textarea", "label": "The items I will put on my reset list are..."}, {"id": "f2", "type": "textarea", "label": "The day and time I will do the reset is..."}, {"id": "f3", "type": "textarea", "label": "A cue that will remind me is..."}, {"id": "f4", "type": "textarea", "label": "Something that makes it more enjoyable is..."}, {"id": "f5", "type": "textarea", "label": "What I want to change after a week is..."}]'::jsonb, array['ADHD', 'organization', 'routines']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('morning-routine-race-track-1005a', 'Morning Routine Race Track', 'kids'::resource_kind, 'A child draws a race track with a stop for each morning step and a parent who cheers at the finish.', 'Help a child follow a morning routine through a visual path they build themselves.', array['Children']::text[], '30 minutes', 'The child draws a race track with a pit stop for each morning step, such as clothes, teeth, shoes, and bag. They decorate each stop and put the track at eye level. The parent walks the track with the child for the first days, offers a cheer at the finish, and keeps prompts brief and kind. Adjust the stops together weekly.', '[{"id": "f0", "type": "textarea", "label": "The first pit stop on my track is..."}, {"id": "f1", "type": "textarea", "label": "The next pit stop is..."}, {"id": "f2", "type": "textarea", "label": "The stop I forget the most is..."}, {"id": "f3", "type": "textarea", "label": "What I will do to remember it is..."}, {"id": "f4", "type": "textarea", "label": "How I want my parent to cheer for me is..."}]'::jsonb, array['ADHD', 'children', 'routines']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('trust-rebuilding-check-in-plan-1005b', 'Trust Rebuilding Check-In Plan', 'couples'::resource_kind, 'Partners agree on a short regular check-in about substance use, urges and honesty, with a part for each.', 'Give a couple a predictable, low-heat way to talk about recovery and rebuild trust.', array['Couples']::text[], '30 minutes, then weekly', 'Run this in session so both partners hear the agreement as it is made. The partner in recovery names what they will share and when; the other partner names what they will ask and how they will respond to hard news. Watch for the check-in turning into questioning, and help them keep it brief, scheduled and kind.', '[{"id": "f0", "type": "textarea", "label": "Partner in recovery: what I will share at each check-in (urges, hard moments, slips)"}, {"id": "f1", "type": "textarea", "label": "Partner in recovery: one thing I will do when I notice I want to hide something"}, {"id": "f2", "type": "textarea", "label": "Supporting partner: the questions I will ask, and the ones I will leave alone"}, {"id": "f3", "type": "textarea", "label": "Supporting partner: how I will respond when I hear something hard"}, {"id": "f4", "type": "textarea", "label": "When and where we will check in, and how long it will last"}, {"id": "f5", "type": "textarea", "label": "What we will do if a check-in gets heated"}, {"id": "f6", "type": "textarea", "label": "One thing each of us appreciates about the other''s effort this week"}]'::jsonb, array['addiction', 'communication', 'relationship issues']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('refusal-skills-role-play-cards-1005b', 'Saying No Practice Role-Play Cards', 'game'::resource_kind, 'A card game where players practice saying no to offers of substances in realistic, low-stakes scenes.', 'Build confidence and ready phrases for turning down substance offers.', array['Adults', 'Teens', 'Groups']::text[], '30 minutes', 'Write scenario cards together beforehand: a friend at a party, a coworker after work, a family gathering. Players draw a card, take the offerer or the refuser role, then swap. Debrief on which phrases felt natural and which felt forced. Keep it playful at first and raise realism gradually, following the client''s pace.', '[{"id": "f0", "type": "textarea", "label": "A situation where someone might offer me a substance"}, {"id": "f1", "type": "textarea", "label": "The first thing I would say, word for word"}, {"id": "f2", "type": "textarea", "label": "What I would do with my body (move, hold a drink, leave)"}, {"id": "f3", "type": "textarea", "label": "What the offerer might say to push back"}, {"id": "f4", "type": "textarea", "label": "My second reply if they push"}, {"id": "f5", "type": "textarea", "label": "The phrase from the game I want to keep"}, {"id": "f6", "type": "textarea", "label": "Who I can text afterward to say I handled it"}]'::jsonb, array['addiction', 'urges', 'skills']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('choice-point-for-urges-1005b', 'Choice Point for Urges', 'act'::resource_kind, 'An ACT choice point map for a moment of substance use urge, sorting moves toward values and moves away.', 'Help a client notice a hooked moment and pick the next step on purpose.', array['Adults', 'Teens']::text[], '25 minutes', 'Draw the choice point with the client: the situation at the top, a fork below. Moves away from what matters are often quick relief; moves toward are usually harder in the moment. Use a recent real urge and avoid shaming the away moves, since they usually make sense. Revisit the same sheet after practice.', '[{"id": "f0", "type": "textarea", "label": "A recent moment when I felt an urge to use"}, {"id": "f1", "type": "textarea", "label": "Thoughts and feelings that showed up in that moment"}, {"id": "f2", "type": "textarea", "label": "What I did, or might have done, that moves me away from what matters"}, {"id": "f3", "type": "textarea", "label": "What I did, or could do, that moves me toward what matters"}, {"id": "f4", "type": "textarea", "label": "What the away move gives me, and what it costs later"}, {"id": "f5", "type": "textarea", "label": "Who or what matters most that I want to move toward"}, {"id": "f6", "type": "textarea", "label": "A small toward move I will try next time"}]'::jsonb, array['addiction', 'core ACT', 'values']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('free-time-rebuild-planner-1005b', 'Free Time Rebuild Planner', 'worksheet'::resource_kind, 'A weekly planner for filling the hours that used to belong to substance use with chosen activities.', 'Replace empty or risky stretches of the week with planned, valued activity.', array['Adults', 'Teens']::text[], '30 minutes, then one week', 'Start by listing the times of day that used to involve substance use, because those are usually the open gaps. Help the client choose activities that are realistic and personally meaningful, not just distracting. Review next session what happened, and adjust without judgment if plans fell through.', '[{"id": "f0", "type": "textarea", "label": "The times of day or week that used to involve substance use"}, {"id": "f1", "type": "textarea", "label": "What I miss about those times, and what I do not miss"}, {"id": "f2", "type": "textarea", "label": "Activities I used to enjoy before substance use took over"}, {"id": "f3", "type": "textarea", "label": "New things I would like to try"}, {"id": "f4", "type": "textarea", "label": "My plan for the riskiest time block this week"}, {"id": "f5", "type": "textarea", "label": "Who could join me or check in"}, {"id": "f6", "type": "textarea", "label": "What I will do if the plan falls apart"}]'::jsonb, array['addiction', 'routines', 'behavioral activation']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('evening-self-soothing-kit-1005b', 'Evening Self-Soothing Kit', 'dbt'::resource_kind, 'A DBT self-soothe through the five senses menu built for the hours when substance use urges tend to rise.', 'Give a client a ready set of soothing options for urge-heavy evenings.', array['Adults', 'Teens']::text[], '25 minutes', 'Work through the five senses with the client and have them name specific items they can actually get hold of on an evening: a tea, a playlist, a blanket. Stress that this does not remove urges but gives them something to do while the urge passes. Suggest keeping a physical kit and checking how it worked afterward.', '[{"id": "f0", "type": "textarea", "label": "Something I can see that calms me"}, {"id": "f1", "type": "textarea", "label": "Something I can hear that calms me"}, {"id": "f2", "type": "textarea", "label": "Something I can smell that calms me"}, {"id": "f3", "type": "textarea", "label": "Something I can taste that calms me"}, {"id": "f4", "type": "textarea", "label": "Something I can touch or wear that calms me"}, {"id": "f5", "type": "textarea", "label": "The time of evening when urges are strongest"}, {"id": "f6", "type": "textarea", "label": "Which two items I will set out before that time"}]'::jsonb, array['addiction', 'distress tolerance', 'self-soothing']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('calm-down-corner-builder-1005b', 'Calm Down Corner Builder', 'kids'::resource_kind, 'A child and parent build a cozy calm corner at home and decide together what goes in it.', 'Give a child a place and a set of tools for cooling off that they chose themselves.', array['Children']::text[], '45 minutes', 'The parent and child gather pillows, drawing paper and sensory items and set up the corner together, with the child making the choices. The parent explains the corner is a place to get calm, not a punishment, and practices using it once when everyone is calm. If a child discloses harm at home, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "The name I gave my calm corner"}, {"id": "f1", "type": "textarea", "label": "Three things I picked to put in it"}, {"id": "f2", "type": "textarea", "label": "What my body feels like when I need to go there"}, {"id": "f3", "type": "textarea", "label": "What I do first when I get there"}, {"id": "f4", "type": "textarea", "label": "What my parent does when I am in my corner"}, {"id": "f5", "type": "textarea", "label": "How I know I am ready to come back out"}, {"id": "f6", "type": "textarea", "label": "What I want to tell my parent after I cool off"}]'::jsonb, array['anger management', 'children', 'play']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('cool-down-relay-game-1005b', 'Cool Down Relay Game', 'game'::resource_kind, 'A team relay where players race to complete calming skills cards instead of racing at full speed.', 'Make practicing cooling skills active, fun and memorable in a group.', array['Teens', 'Groups']::text[], '30 minutes', 'Set up stations with calming skills such as paced breathing, a cold drink, stretching and counting. Teams take turns, and players must finish each skill slowly to score. The twist of slowing down on purpose usually lands well with teens. Debrief on which skills worked best and when in real life each would be useful.', '[{"id": "f0", "type": "textarea", "label": "The skill that was easiest to do slowly"}, {"id": "f1", "type": "textarea", "label": "The skill that was hardest to do slowly"}, {"id": "f2", "type": "textarea", "label": "What changed in my body during the relay"}, {"id": "f3", "type": "textarea", "label": "A moment this week when I could use that skill"}, {"id": "f4", "type": "textarea", "label": "What I would say to a teammate who is about to blow up"}, {"id": "f5", "type": "textarea", "label": "The skill I will keep in my toolkit"}]'::jsonb, array['anger management', 'group', 'play']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('checking-the-facts-on-anger-1005b', 'Checking the Facts on Anger', 'dbt'::resource_kind, 'A DBT check the facts sheet separating what happened from the story attached to it before acting on anger.', 'Slow down the jump from an event to an angry reaction.', array['Adults', 'Teens']::text[], '20 minutes', 'Choose a recent angry moment. Have the client describe only what a camera would have recorded, then list the interpretations and assumptions. Ask whether the emotion and its intensity fit the facts, and what action would fit. Be careful not to suggest anger is wrong; the aim is a choice about the response.', '[{"id": "f0", "type": "textarea", "label": "What happened, as a camera would have recorded it"}, {"id": "f1", "type": "textarea", "label": "What I told myself it meant"}, {"id": "f2", "type": "textarea", "label": "Other possible explanations"}, {"id": "f3", "type": "textarea", "label": "What I was feeling and how strong it was (0 to 10)"}, {"id": "f4", "type": "textarea", "label": "Does the strength fit the facts, as far as I can tell?"}, {"id": "f5", "type": "textarea", "label": "What I wanted to do"}, {"id": "f6", "type": "textarea", "label": "What I could do that fits what matters to me"}]'::jsonb, array['anger management', 'emotion regulation', 'skills']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('hot-thought-rewind-sheet-1005b', 'Hot Thought Rewind Sheet', 'cbt'::resource_kind, 'A CBT thought record tuned for angry thoughts, such as demands, blame and mind reading.', 'Help a client catch and test the hot thoughts that fuel anger.', array['Adults', 'Teens']::text[], '25 minutes', 'Anger thoughts often sound like ''should'', ''always'' and ''on purpose''. Help the client pick out the hottest thought from a recent incident, then look at the facts for and against it. Avoid arguing them out of their feelings; the goal is a more balanced thought they still believe, and a response they can choose.', '[{"id": "f0", "type": "textarea", "label": "The situation that set off my anger"}, {"id": "f1", "type": "textarea", "label": "The hottest thought I had"}, {"id": "f2", "type": "textarea", "label": "Words in it like always, never, should or on purpose"}, {"id": "f3", "type": "textarea", "label": "Facts that fit this thought"}, {"id": "f4", "type": "textarea", "label": "Facts that do not fit it"}, {"id": "f5", "type": "textarea", "label": "A more balanced way to say it"}, {"id": "f6", "type": "textarea", "label": "How angry I feel now (0 to 10)"}]'::jsonb, array['anger management', 'core CBT', 'thinking traps']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('anger-and-what-i-value-compass-1005b', 'Anger and What I Value Compass', 'act'::resource_kind, 'An ACT values exercise asking what an angry moment shows about what matters and how to act on it well.', 'Connect anger to the value underneath it and pick a response in line with it.', array['Adults']::text[], '30 minutes', 'Many clients find anger has a value under it, such as fairness, respect or protecting someone. Help them name that value and then compare what anger-driven actions cost against what value-driven actions would look like. Avoid framing anger as a problem to remove; the point is room to choose a response.', '[{"id": "f0", "type": "textarea", "label": "A recent time I was angry"}, {"id": "f1", "type": "textarea", "label": "What I was trying to protect or stand up for"}, {"id": "f2", "type": "textarea", "label": "The value underneath it, in a word or two"}, {"id": "f3", "type": "textarea", "label": "What I did when angry, and what it cost"}, {"id": "f4", "type": "textarea", "label": "What acting on that value could look like instead"}, {"id": "f5", "type": "textarea", "label": "What I would have to feel or tolerate to do that"}, {"id": "f6", "type": "textarea", "label": "One small way to do it this week"}]'::jsonb, array['anger management', 'core ACT', 'values']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('mental-ritual-spotter-1005b', 'Mental Ritual Spotter', 'worksheet'::resource_kind, 'A worksheet to help a client notice hidden mental rituals such as checking, reviewing and counting in the head.', 'Help a client see the covert rituals that keep an intrusive thought cycle going.', array['Adults', 'Teens']::text[], '25 minutes', 'Many people only count visible actions as rituals and miss what happens in the head. Go through the list with curiosity and not criticism, and let the client sort what actually feels like a ritual from ordinary thinking. This is a noticing tool for you to work from, and it does not replace your own judgment.', '[{"id": "f0", "type": "textarea", "label": "An intrusive thought that shows up for me"}, {"id": "f1", "type": "textarea", "label": "What I do in my head right after it (review, repeat, check, argue)"}, {"id": "f2", "type": "textarea", "label": "How long I spend doing that"}, {"id": "f3", "type": "textarea", "label": "What I hope it will do for me"}, {"id": "f4", "type": "textarea", "label": "What happens to the thought afterward"}, {"id": "f5", "type": "textarea", "label": "Mental moves I only noticed while filling this out"}, {"id": "f6", "type": "textarea", "label": "One I would like to watch for this week"}]'::jsonb, array['OCD', 'monitoring', 'response prevention']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('doubt-dial-experiment-1005b', 'Doubt Dial Experiment', 'cbt'::resource_kind, 'A behavioral experiment where a client rates a feared outcome, tries a doubtful situation, and compares.', 'Let a client test what happens when they tolerate doubt without checking.', array['Adults', 'Teens']::text[], '30 minutes, then one week', 'Choose a small, specific feared prediction with the client and agree on the exact experiment. They rate their belief in the prediction before and after, noting what they did instead of the ritual. Keep it modest at first, and discuss results without pushing certainty, since the lesson is about living with some doubt.', '[{"id": "f0", "type": "textarea", "label": "The doubt or fear I am testing"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen"}, {"id": "f2", "type": "textarea", "label": "How much I believe that (0 to 100)"}, {"id": "f3", "type": "textarea", "label": "What I will do, and what I will not do (my usual ritual)"}, {"id": "f4", "type": "textarea", "label": "What actually happened"}, {"id": "f5", "type": "textarea", "label": "How much I believe the prediction now (0 to 100)"}, {"id": "f6", "type": "textarea", "label": "What I learned about doubt"}]'::jsonb, array['OCD', 'behavioral experiment', 'uncertainty']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('values-over-rituals-compass-1005b', 'Values Before Rituals Direction Sheet', 'act'::resource_kind, 'An ACT compass comparing time given to rituals with time given to what matters in the client''s life.', 'Help a client see what rituals take from valued living and where to redirect.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask the client to name their values in several areas of life, then estimate how much time rituals take from each. This can bring up grief or frustration, so give it room. Choose one small, values-based action to do in the place of a ritual-heavy stretch, and keep the language kind and free of blame.', '[{"id": "f0", "type": "textarea", "label": "Three things that matter most to me"}, {"id": "f1", "type": "textarea", "label": "How rituals take time from each of those"}, {"id": "f2", "type": "textarea", "label": "A time of day when rituals take the most"}, {"id": "f3", "type": "textarea", "label": "What I would like to do with that time"}, {"id": "f4", "type": "textarea", "label": "What I fear might happen if I did it"}, {"id": "f5", "type": "textarea", "label": "A small values step I will try this week"}, {"id": "f6", "type": "textarea", "label": "What I will say to myself if the urge to ritualize gets loud"}]'::jsonb, array['OCD', 'core ACT', 'values']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('supportive-not-reassuring-phrase-card-1005b', 'Supportive Not Reassuring Phrase Card', 'couples'::resource_kind, 'Partners write supportive replies that care for the person without answering the doubt.', 'Help a partner support their loved one without feeding the reassurance cycle.', array['Couples']::text[], '30 minutes', 'Work with the partner who is asked for reassurance to draft warm replies that recognize feelings and leave the question unanswered, and with the partner who experiences OCD to say what kind of reply would help them. Role-play a few. Expect the supporting partner to feel guilty about holding back, and name that.', '[{"id": "f0", "type": "textarea", "label": "Partner with intrusive thoughts: how I ask for reassurance"}, {"id": "f1", "type": "textarea", "label": "Partner with intrusive thoughts: what kind of reply helps me later"}, {"id": "f2", "type": "textarea", "label": "Supporting partner: how it feels to be asked"}, {"id": "f3", "type": "textarea", "label": "Supporting partner: three warm replies that do not answer the doubt"}, {"id": "f4", "type": "textarea", "label": "How we will signal to each other that the question is a ritual"}, {"id": "f5", "type": "textarea", "label": "What we will do together afterward instead"}, {"id": "f6", "type": "textarea", "label": "What we will tell each other if it gets tense"}]'::jsonb, array['OCD', 'family accommodation', 'couples']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('thought-bubble-pass-game-1005b', 'Thought Bubble Pass Game', 'game'::resource_kind, 'A group game where intrusive-style thoughts on cards are passed along and acknowledged without reacting.', 'Practice letting a thought be there without acting on it, through play.', array['Teens', 'Groups']::text[], '25 minutes', 'Write neutral, silly or mildly uncomfortable thoughts on cards, avoiding anything graphic or truly distressing. Players pass the card clockwise and say, ''I notice a thought that...'' then hand it on. Choose content to fit the group so no one is flooded. Debrief on how it felt to notice without arguing or fixing.', '[{"id": "f0", "type": "textarea", "label": "A thought that was easy to pass along"}, {"id": "f1", "type": "textarea", "label": "A thought that felt harder to pass"}, {"id": "f2", "type": "textarea", "label": "What I noticed in my body"}, {"id": "f3", "type": "textarea", "label": "What I wanted to do when the thought arrived"}, {"id": "f4", "type": "textarea", "label": "What it was like to just say ''I notice a thought''"}, {"id": "f5", "type": "textarea", "label": "A moment this week I could try it"}, {"id": "f6", "type": "textarea", "label": "What I would tell a friend who gets stuck on a thought"}]'::jsonb, array['OCD', 'group', 'defusion']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('calm-breathing-pinwheel-craft-1005b', 'Calm Breathing Pinwheel Craft', 'kids'::resource_kind, 'A child makes a pinwheel and uses it to practice slow, steady breaths with a parent.', 'Give a child a hands-on way to practice slowing their breathing.', array['Children']::text[], '30 minutes', 'The child decorates and builds a paper pinwheel, then practices blowing it gently and slowly with the parent. Explain that fast breathing is part of how a body gets ready to be brave, and practice when calm so it is familiar. The parent models along with the child. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "The colors I picked for my pinwheel"}, {"id": "f1", "type": "textarea", "label": "What my body feels like when it gets really scared"}, {"id": "f2", "type": "textarea", "label": "What happens to my pinwheel when I breathe fast"}, {"id": "f3", "type": "textarea", "label": "What happens when I breathe slow"}, {"id": "f4", "type": "textarea", "label": "Who I practiced with"}, {"id": "f5", "type": "textarea", "label": "Where I will keep my pinwheel"}, {"id": "f6", "type": "textarea", "label": "How I felt after the slow breaths"}]'::jsonb, array['panic attacks', 'children', 'play']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('sensation-surprise-card-game-1005b', 'Sensation Surprise Card Game', 'game'::resource_kind, 'A card game where players safely bring on harmless body sensations and rate how strong and how safe they feel.', 'Practice noticing body sensations without alarm in a playful, structured way.', array['Teens', 'Groups']::text[], '30 minutes', 'Cards name safe activities such as spinning slowly, breathing through a straw or jogging in place. Players take a turn, rate the sensation, and say what they noticed. Choose cards to fit the client''s health, and use your judgment on pacing. Debrief on what the sensations felt like and what thoughts came with them.', '[{"id": "f0", "type": "textarea", "label": "The card I drew"}, {"id": "f1", "type": "textarea", "label": "The sensations I noticed"}, {"id": "f2", "type": "textarea", "label": "How strong they felt (0 to 10)"}, {"id": "f3", "type": "textarea", "label": "The thought that came with them"}, {"id": "f4", "type": "textarea", "label": "What happened to the sensation after a minute"}, {"id": "f5", "type": "textarea", "label": "A sensation that surprised me"}, {"id": "f6", "type": "textarea", "label": "What I want to practice at home"}]'::jsonb, array['panic attacks', 'exposure', 'interoception']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('safety-behavior-inventory-1005b', 'Safety Behavior Inventory', 'worksheet'::resource_kind, 'A worksheet listing the things a client does to feel safe around panic, and what each costs them.', 'Help a client see which safety habits keep life small.', array['Adults', 'Teens']::text[], '30 minutes', 'Safety behaviors such as carrying water, sitting near exits or checking a pulse can feel necessary. List them without criticism and note what each one gives and costs. Choose with the client which to test dropping first, if any, and in what order. This is a conversation starter for your own clinical judgment.', '[{"id": "f0", "type": "textarea", "label": "Things I carry or keep close in case of panic"}, {"id": "f1", "type": "textarea", "label": "Places or seats I choose to feel safe"}, {"id": "f2", "type": "textarea", "label": "Things I check in my body"}, {"id": "f3", "type": "textarea", "label": "What each one gives me"}, {"id": "f4", "type": "textarea", "label": "What each one costs me"}, {"id": "f5", "type": "textarea", "label": "Which one I might try without first, and when"}, {"id": "f6", "type": "textarea", "label": "What I expect to happen if I do"}]'::jsonb, array['panic attacks', 'avoidance', 'monitoring']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('panic-prediction-experiment-1005b', 'Panic Prediction Experiment', 'cbt'::resource_kind, 'A behavioral experiment where a client records what they predict during panic and what actually happened.', 'Compare feared predictions about panic sensations with real outcomes.', array['Adults', 'Teens']::text[], 'Two weeks', 'Ask the client to write their prediction when a panic wave begins, such as ''I will faint'', and then note what happened. Review a few entries together and look for patterns, such as predictions that did not come true. Keep it curious and not argumentative, and leave medical questions to the client''s doctor.', '[{"id": "f0", "type": "textarea", "label": "Where I was when the panic wave started"}, {"id": "f1", "type": "textarea", "label": "What I felt in my body"}, {"id": "f2", "type": "textarea", "label": "What I predicted would happen"}, {"id": "f3", "type": "textarea", "label": "How sure I was (0 to 100)"}, {"id": "f4", "type": "textarea", "label": "What actually happened"}, {"id": "f5", "type": "textarea", "label": "How long the strongest part lasted"}, {"id": "f6", "type": "textarea", "label": "What I notice across my entries"}]'::jsonb, array['panic attacks', 'behavioral experiment', 'thinking traps']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('making-room-for-alarm-practice-1005b', 'Making Room for Alarm Practice', 'act'::resource_kind, 'An ACT practice for letting panic sensations be present while moving toward something that matters.', 'Practice making room for alarm sensations while doing what the client values.', array['Adults']::text[], '20 minutes', 'Guide the client to notice panic sensations, name them, breathe around them and keep doing a small valued activity anyway. This is not about getting rid of panic. Use a mild sensation first and pace to the client''s comfort. Ask afterward what it was like to carry the feeling along instead of fighting it.', '[{"id": "f0", "type": "textarea", "label": "A valued activity I want to do even with panic around"}, {"id": "f1", "type": "textarea", "label": "Sensations I notice when alarm shows up"}, {"id": "f2", "type": "textarea", "label": "How I usually fight or escape them"}, {"id": "f3", "type": "textarea", "label": "What it would look like to make room for them"}, {"id": "f4", "type": "textarea", "label": "What I noticed when I tried"}, {"id": "f5", "type": "textarea", "label": "What I did anyway"}, {"id": "f6", "type": "textarea", "label": "What I will practice this week"}]'::jsonb, array['panic attacks', 'core ACT', 'willingness']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('tantrum-storm-shelter-plan-1005c', 'Tantrum Storm Shelter Plan', 'kids'::resource_kind, 'A parent and child build a cozy calm-down shelter and decide together how it gets used.', 'Give a child and parent a shared, practiced place and script for big feelings.', array['Children']::text[], '30 minutes', 'Have the parent and child build a small shelter from pillows and a blanket, then decorate it with calming items the child picks. The point is rehearsal while everyone is calm, so the shelter is a place the child chooses rather than a punishment. Coach the parent to stay nearby and quiet. If a child discloses anything worrying, remember your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "The name my child gave our shelter"}, {"id": "f1", "type": "textarea", "label": "Three things we put inside it to help us feel calm"}, {"id": "f2", "type": "textarea", "label": "The words the parent will say when a storm starts"}, {"id": "f3", "type": "textarea", "label": "What my child wants the parent to do while they are inside"}, {"id": "f4", "type": "textarea", "label": "How we will know the storm has passed"}, {"id": "f5", "type": "textarea", "label": "When we will practice using the shelter this week"}]'::jsonb, array['parenting', 'children', 'regulation']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('sibling-squabble-referee-game-1005c', 'Sibling Squabble Referee Game', 'game'::resource_kind, 'A turn-taking card game where siblings and parents practice fair solutions to common arguments.', 'Let siblings rehearse fair, calm solutions to everyday arguments through play.', array['Children', 'Groups']::text[], '30 minutes', 'Write common squabbles on cards, such as who sits where or whose turn it is. Players draw a card, act as the referee, and propose a fair fix, with the parent playing too and sometimes giving a deliberately unfair answer for the children to catch. In the debrief, ask which fixes felt fair to everyone. Keep it silly so the children stay open to it.', '[{"id": "f0", "type": "textarea", "label": "A squabble card we drew"}, {"id": "f1", "type": "textarea", "label": "The fix I suggested as referee"}, {"id": "f2", "type": "textarea", "label": "Whether everyone felt it was fair, and why"}, {"id": "f3", "type": "textarea", "label": "A squabble from home we could try a fix on"}, {"id": "f4", "type": "textarea", "label": "A fair fix we want to remember"}, {"id": "f5", "type": "textarea", "label": "What the parent will do next time a squabble starts"}]'::jsonb, array['parenting', 'family', 'play', 'communication']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('good-enough-parent-thought-swap-1005c', 'Good Enough Parent Thought Swap', 'cbt'::resource_kind, 'A thought-swap sheet that pairs harsh parenting thoughts with balanced, realistic alternatives.', 'Help a parent notice perfectionistic parenting thoughts and test more balanced ones.', array['Adults']::text[], '20 minutes', 'Walk the parent through one recent moment when they judged themselves harshly, then separate the situation, the thought and the feeling. Ask them to write a balanced alternative they could believe at least partly. Parents often write what sounds nice but feels untrue, so ask for a rating of belief before and after. Use it alongside your own formulation of the parent''s patterns.', '[{"id": "f0", "type": "textarea", "label": "The parenting moment I judged myself about"}, {"id": "f1", "type": "textarea", "label": "The thought that showed up, in my own words"}, {"id": "f2", "type": "textarea", "label": "How strongly I believed it, from 0 to 100"}, {"id": "f3", "type": "textarea", "label": "What I would say to a friend in the same spot"}, {"id": "f4", "type": "textarea", "label": "A more balanced thought I can partly believe"}, {"id": "f5", "type": "textarea", "label": "How strongly I believe the balanced thought now"}]'::jsonb, array['parenting', 'thinking traps', 'core CBT', 'self-criticism']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('hooked-parent-defusion-cards-1005c', 'Hooked Parent Defusion Cards', 'act'::resource_kind, 'Cards that help a parent notice sticky parenting thoughts and hold them lightly while acting on values.', 'Help a parent unhook from rigid parenting stories and act on what matters to them.', array['Adults']::text[], '25 minutes', 'Ask the parent to name the stories that grab them in hard moments, such as I am failing or my child should not act like this, and write each as a card beginning with I am having the thought that. Practice saying the cards aloud, then choose one small values-based parenting action to take with the thought still present. Keep the tone playful rather than corrective.', '[{"id": "f0", "type": "textarea", "label": "A sticky story I tell myself as a parent"}, {"id": "f1", "type": "textarea", "label": "The same story starting with I am having the thought that"}, {"id": "f2", "type": "textarea", "label": "What the thought pushes me to do"}, {"id": "f3", "type": "textarea", "label": "What I want my parenting to stand for"}, {"id": "f4", "type": "textarea", "label": "One small action I can take with the thought still there"}, {"id": "f5", "type": "textarea", "label": "How I will notice when I get hooked this week"}]'::jsonb, array['parenting', 'defusion', 'values', 'core ACT']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('parenting-partners-weekly-check-in-1005c', 'Parenting Partners Weekly Check-In', 'couples'::resource_kind, 'Two parents each name what is working, what feels heavy and what support they want from each other.', 'Give two parents a short, structured way to align and support each other each week.', array['Couples']::text[], '20 minutes', 'Each partner fills in their own part, then they take turns reading aloud while the other listens without fixing. Partner A speaks first one week and Partner B the next. Watch for the check-in turning into a list of complaints; steer back to one request each. Use it as a bridge between sessions and adapt it to the family''s rhythm.', '[{"id": "f0", "type": "textarea", "label": "Partner A: something I appreciated about how we parented this week"}, {"id": "f1", "type": "textarea", "label": "Partner B: something I appreciated about how we parented this week"}, {"id": "f2", "type": "textarea", "label": "Partner A: what felt heaviest for me this week"}, {"id": "f3", "type": "textarea", "label": "Partner B: what felt heaviest for me this week"}, {"id": "f4", "type": "textarea", "label": "Partner A: one specific thing I would like help with"}, {"id": "f5", "type": "textarea", "label": "Partner B: one specific thing I would like help with"}]'::jsonb, array['parenting', 'couples', 'communication', 'support']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('nighttime-worry-parking-lot-1005c', 'Nighttime Worry Parking Lot', 'cbt'::resource_kind, 'A bedside worksheet where a new parent parks worries on paper and plans a time to revisit them.', 'Help a new parent set down nighttime worries and sort which ones need action.', array['Adults']::text[], '15 minutes', 'Introduce this as a bedside page for the worries that show up during night feeds or waking. The parent jots each worry, then marks whether it has an action for tomorrow or is a what-if to let sit. Review together how it went; many parents find the act of writing helps but need permission to keep it brief. Adapt it to what the parent is carrying.', '[{"id": "f0", "type": "textarea", "label": "The worry on my mind right now"}, {"id": "f1", "type": "textarea", "label": "Whether it needs an action tomorrow or is a what-if"}, {"id": "f2", "type": "textarea", "label": "If it needs action, the one small step I can take"}, {"id": "f3", "type": "textarea", "label": "A kind thing I can tell myself while I wait"}, {"id": "f4", "type": "textarea", "label": "When I will look at this page in daylight"}, {"id": "f5", "type": "textarea", "label": "Who I could share the heavy worries with"}]'::jsonb, array['perinatal and postpartum', 'worry', 'sleep']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('wise-mind-moments-for-new-parents-1005c', 'Wise Mind Moments for New Parents', 'dbt'::resource_kind, 'A brief wise-mind practice a new parent can use between feeds, matching feeling and reasoning.', 'Give a new parent a quick way to find a steady, balanced response in tiring moments.', array['Adults']::text[], '15 minutes', 'Teach wise mind as the place where feeling and reasoning overlap, and practice it with one recent moment of overwhelm. Ask the parent to name what the emotional mind said, what the reasonable mind said, and what wise mind suggests. Keep the practice short enough to fit between feeds. Check in on how realistic each step is given how little sleep they are getting.', '[{"id": "f0", "type": "textarea", "label": "A recent moment I felt overwhelmed"}, {"id": "f1", "type": "textarea", "label": "What my emotional mind said"}, {"id": "f2", "type": "textarea", "label": "What my reasonable mind said"}, {"id": "f3", "type": "textarea", "label": "What my wise mind says, in one sentence"}, {"id": "f4", "type": "textarea", "label": "One breath or pause I can use before the next feed"}, {"id": "f5", "type": "textarea", "label": "A cue in my day that will remind me to try this"}]'::jsonb, array['perinatal and postpartum', 'regulation', 'mindfulness', 'skills']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('visitor-boundaries-script-sheet-1005c', 'Visitor Boundaries Script Sheet', 'worksheet'::resource_kind, 'A script sheet for setting kind limits on visitors, advice and help in the weeks after a baby arrives.', 'Help a new parent plan clear, warm limits around visitors and unsolicited advice.', array['Adults']::text[], '20 minutes', 'Many new parents feel guilty saying no to well-meaning family. Use the sheet to name which visits and offers they want, and to draft short sentences they can say or text. Rehearse one or two aloud in session so the words are familiar. The goal is the parent''s comfort, not a rulebook; let them decide what to include and revisit it as needs change.', '[{"id": "f0", "type": "textarea", "label": "Who I want to see in the next few weeks"}, {"id": "f1", "type": "textarea", "label": "How long and how often feels manageable"}, {"id": "f2", "type": "textarea", "label": "What kind of help I would like most"}, {"id": "f3", "type": "textarea", "label": "A kind sentence I can use to say not yet"}, {"id": "f4", "type": "textarea", "label": "A sentence I can use when advice is not welcome"}, {"id": "f5", "type": "textarea", "label": "Who will help me say these things if I freeze"}]'::jsonb, array['perinatal and postpartum', 'boundaries', 'support', 'communication']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('newborn-care-card-swap-1005c', 'Newborn Care Card Swap', 'couples'::resource_kind, 'Partners sort caregiving and household tasks onto cards and trade them to find a sustainable shape.', 'Help two new parents see all the care work and renegotiate who does what.', array['Couples']::text[], '30 minutes', 'Write every task, from night feeds to laundry to remembering appointments, on cards, including the invisible mental load. Each partner sorts the cards into who does it now, then they swap two or three cards and name the part they will each take. Name both partners'' parts in the summary. Expect tiredness to color the conversation, so keep each turn short and kind.', '[{"id": "f0", "type": "textarea", "label": "Partner A: tasks I carry right now"}, {"id": "f1", "type": "textarea", "label": "Partner B: tasks I carry right now"}, {"id": "f2", "type": "textarea", "label": "Partner A: one card I would like to swap and why"}, {"id": "f3", "type": "textarea", "label": "Partner B: one card I would like to swap and why"}, {"id": "f4", "type": "textarea", "label": "Partner A: what I will take on this week"}, {"id": "f5", "type": "textarea", "label": "Partner B: what I will take on this week"}]'::jsonb, array['perinatal and postpartum', 'couples', 'support', 'relationships']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('mixed-feelings-welcome-practice-1005c', 'Mixed Feelings Welcome Practice', 'act'::resource_kind, 'An acceptance practice for making room for joy, grief and ambivalence all at once after a baby arrives.', 'Help a new parent allow mixed feelings about parenthood without judging them.', array['Adults']::text[], '20 minutes', 'Invite the parent to name all the feelings present, including ones they think they should not have, and to notice they can coexist with caring for the baby. Use a simple willingness exercise where each feeling gets a place at the table. Be alert for shame; normalize that mixed feelings are common and leave it to your judgment whether other support is needed.', '[{"id": "f0", "type": "textarea", "label": "A feeling about this new chapter that is easy to say"}, {"id": "f1", "type": "textarea", "label": "A feeling I find harder to admit"}, {"id": "f2", "type": "textarea", "label": "Where I notice each feeling in my body"}, {"id": "f3", "type": "textarea", "label": "What I tell myself about having these feelings"}, {"id": "f4", "type": "textarea", "label": "What I would say to a friend who felt the same"}, {"id": "f5", "type": "textarea", "label": "One small thing I care about that I can do with the feelings still here"}]'::jsonb, array['perinatal and postpartum', 'acceptance', 'values', 'self-compassion']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('inner-critic-comic-strip-1005c', 'Inner Critic Comic Strip', 'kids'::resource_kind, 'A child draws their inner critic and a kind helper as comic characters and scripts their conversation.', 'Help a child separate from a harsh inner voice and practice a kinder reply.', array['Children', 'Teens']::text[], '30 minutes', 'Have the child draw a three-panel comic: the critic says something mean, the helper responds, and the child decides what to do. Let them design the characters however they like. Invite the parent to listen to the finished comic and to say one thing they appreciate about the child. If a child shares anything worrying, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "What my inner critic looks like"}, {"id": "f1", "type": "textarea", "label": "What the critic says that bothers me"}, {"id": "f2", "type": "textarea", "label": "What my kind helper looks like"}, {"id": "f3", "type": "textarea", "label": "What the helper says back"}, {"id": "f4", "type": "textarea", "label": "What I decide to do next"}, {"id": "f5", "type": "textarea", "label": "Who I could show this comic to"}]'::jsonb, array['self-esteem', 'children', 'self-criticism', 'play']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('compliment-receiving-rehearsal-1005c', 'Compliment Receiving Rehearsal', 'dbt'::resource_kind, 'A skills sheet for taking in praise with a simple thank-you and noticing the urge to deflect.', 'Help a client practice accepting a compliment without discounting it.', array['Adults', 'Teens']::text[], '20 minutes', 'Role-play receiving a compliment, noticing the urge to deflect or return one at once. Link it to describing and mindful attention: notice the words, the feeling and the urge, then say thank you and stop. Many clients find this much harder than it sounds, so start with small compliments and let them choose how much to practice outside session.', '[{"id": "f0", "type": "textarea", "label": "A compliment I got recently"}, {"id": "f1", "type": "textarea", "label": "What I said back"}, {"id": "f2", "type": "textarea", "label": "What I felt in my body when I heard it"}, {"id": "f3", "type": "textarea", "label": "The urge I noticed to push the compliment away"}, {"id": "f4", "type": "textarea", "label": "A simple thank-you I can say instead"}, {"id": "f5", "type": "textarea", "label": "A time this week I will practice just saying thanks"}]'::jsonb, array['self-esteem', 'skills', 'mindfulness', 'regulation']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('good-enough-standards-experiment-1005c', 'Good Enough Standards Experiment', 'cbt'::resource_kind, 'A behavioral experiment that tests what happens when a task is done to a good enough standard.', 'Help a client test whether lowering a perfectionist standard changes the feared outcome.', array['Adults', 'Teens']::text[], '25 minutes', 'Pick one small task where the client holds a very high standard, and plan to do it at a good enough level on purpose. Record the prediction, the outcome and what they noticed. Keep the experiment small and agree on it beforehand. Review the result with curiosity and let your clinical judgment guide whether to raise the stakes in the next one.', '[{"id": "f0", "type": "textarea", "label": "The task and the standard I usually hold"}, {"id": "f1", "type": "textarea", "label": "What I think will happen if I do it at good enough"}, {"id": "f2", "type": "textarea", "label": "How strongly I believe that, from 0 to 100"}, {"id": "f3", "type": "textarea", "label": "What I actually did"}, {"id": "f4", "type": "textarea", "label": "What actually happened"}, {"id": "f5", "type": "textarea", "label": "What I take from this about my standards"}]'::jsonb, array['self-esteem', 'behavioral experiment', 'perfectionism', 'core CBT']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('worth-is-not-earned-phrase-cards-1005c', 'Worth Is Not Earned Phrase Cards', 'act'::resource_kind, 'Defusion phrase cards for the stories that tie a person''s worth to performance or approval.', 'Help a client hold worth-based stories lightly and choose actions by values.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to write the I am only worth it if stories on cards, then practice noticing them as thoughts with silly voices or by saying them slowly. Follow with one action chosen from a value, taken with the story still present. Keep the aim on flexibility rather than winning an argument with the thought.', '[{"id": "f0", "type": "textarea", "label": "A story about my worth that shows up often"}, {"id": "f1", "type": "textarea", "label": "How it sounds when I say it slowly"}, {"id": "f2", "type": "textarea", "label": "What it pushes me to do or avoid"}, {"id": "f3", "type": "textarea", "label": "A value I want to act on instead"}, {"id": "f4", "type": "textarea", "label": "One action from that value that I can take this week"}, {"id": "f5", "type": "textarea", "label": "What I will say to myself when the story shows up"}]'::jsonb, array['self-esteem', 'defusion', 'values', 'core ACT']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('strengths-charades-game-1005c', 'Strengths Charades Game', 'game'::resource_kind, 'A group guessing game where players act out strengths seen in themselves and each other.', 'Give a group a playful way to name strengths and receive recognition from others.', array['Groups', 'Teens', 'Children']::text[], '25 minutes', 'Players take turns drawing a strength card, such as patient or brave, and acting out a time they used it while others guess. After each round, someone else adds a time they saw that strength in the player. Debrief by asking what it was like to hear it. Expect some embarrassment and let players pass on a turn.', '[{"id": "f0", "type": "textarea", "label": "The strength I picked"}, {"id": "f1", "type": "textarea", "label": "The story I acted out"}, {"id": "f2", "type": "textarea", "label": "What the group saw in me"}, {"id": "f3", "type": "textarea", "label": "How it felt to be seen this way"}, {"id": "f4", "type": "textarea", "label": "A strength someone else named that I had overlooked"}, {"id": "f5", "type": "textarea", "label": "How I can use a strength this week"}]'::jsonb, array['self-esteem', 'strengths', 'group', 'play']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('small-talk-role-play-deck-1005c', 'Small Talk Role-Play Deck', 'game'::resource_kind, 'A card deck for practicing openers, follow-up questions and graceful exits in low-stakes role-plays.', 'Let a client practice small talk skills in a playful, low-pressure setting.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Make cards with settings like a line at a coffee shop and prompts like ask a follow-up question. Players draw, role-play for a minute and the clinician or group gives one thing that went well. Keep the stakes low and let clients choose their level of challenge. In the debrief ask what they predicted versus what happened.', '[{"id": "f0", "type": "textarea", "label": "The setting I drew"}, {"id": "f1", "type": "textarea", "label": "What I predicted would be hard"}, {"id": "f2", "type": "textarea", "label": "What I said to open the conversation"}, {"id": "f3", "type": "textarea", "label": "One thing that went well"}, {"id": "f4", "type": "textarea", "label": "How anxious I felt, from 0 to 10"}, {"id": "f5", "type": "textarea", "label": "One situation I will try something similar in this week"}]'::jsonb, array['social anxiety', 'communication', 'exposure', 'play']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('blushing-and-shaking-acceptance-practice-1005c', 'Blushing and Shaking Acceptance Practice', 'act'::resource_kind, 'A practice for letting visible anxiety signs be present while staying engaged in a conversation.', 'Help a client stay engaged in social moments with visible anxiety present.', array['Adults', 'Teens']::text[], '25 minutes', 'Explore which visible signs, such as blushing, shaky hands or a trembling voice, the client fears others will notice. Practice letting them be there during a short role-play while the client keeps attention on the other person and their value of connection. Avoid framing the goal as getting rid of the signs. Let your judgment shape the pace.', '[{"id": "f0", "type": "textarea", "label": "The sign of anxiety I most worry people will see"}, {"id": "f1", "type": "textarea", "label": "What I fear people will think"}, {"id": "f2", "type": "textarea", "label": "What I do to hide it"}, {"id": "f3", "type": "textarea", "label": "What I would like to be doing in the conversation instead"}, {"id": "f4", "type": "textarea", "label": "A small way I can let it be there this week"}, {"id": "f5", "type": "textarea", "label": "What I notice when I do"}]'::jsonb, array['social anxiety', 'acceptance', 'values', 'core ACT']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('social-event-teammate-plan-1005c', 'Social Event Teammate Plan', 'couples'::resource_kind, 'A pre-event plan where partners agree on signals, breaks and how to debrief afterward.', 'Help partners support each other through a social event without pressure or rescue.', array['Couples']::text[], '25 minutes', 'The partner who feels social anxiety names what would help, and the other partner names what they can offer without taking over. Agree on a break signal, how long to stay and a kind debrief afterward. Name both partners'' parts. Watch for the supporting partner answering for the other; coach them to let the person take their own turns.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what worries me most about this event"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I can offer during the event"}, {"id": "f2", "type": "textarea", "label": "Partner A: a signal I can use if I need a break"}, {"id": "f3", "type": "textarea", "label": "Partner B: how I will respond to the signal"}, {"id": "f4", "type": "textarea", "label": "Partner A: one thing I want to try at the event"}, {"id": "f5", "type": "textarea", "label": "Partner B: how we will talk about it afterward"}]'::jsonb, array['social anxiety', 'couples', 'support', 'exposure']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('hello-challenge-passport-1005c', 'Hello Challenge Passport', 'kids'::resource_kind, 'A child collects stamps for small, brave social steps like saying hello, with the parent coaching from the side.', 'Help a child take small social steps with a parent cheering from nearby.', array['Children']::text[], '20 minutes', 'Draw a passport together and list small social steps, such as waving at a neighbor or asking a friend a question. The child chooses one at a time and the parent coaches and cheers without doing it for them. Praise the trying, not the outcome. If a child discloses anything worrying, remember your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "A small social step I want to try"}, {"id": "f1", "type": "textarea", "label": "How worried I feel about it, from 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What my parent will do to help"}, {"id": "f3", "type": "textarea", "label": "What happened when I tried it"}, {"id": "f4", "type": "textarea", "label": "How I felt afterward"}, {"id": "f5", "type": "textarea", "label": "The next stamp I want to earn"}]'::jsonb, array['social anxiety', 'children', 'exposure', 'play']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('social-avoidance-cost-ledger-1005c', 'Social Avoidance Cost Ledger', 'worksheet'::resource_kind, 'A ledger that lists what avoiding social situations has protected and what it has cost.', 'Help a client weigh the short-term relief of avoidance against its costs.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client to list situations they avoid, what the avoidance gives them in the moment and what it has taken from their life. Work toward the client''s own words about what they want back. Avoid arguing them out of the relief; the relief is real. Use the ledger to choose a first small step together.', '[{"id": "f0", "type": "textarea", "label": "A social situation I tend to avoid"}, {"id": "f1", "type": "textarea", "label": "What avoiding it gives me right away"}, {"id": "f2", "type": "textarea", "label": "What it has cost me over time"}, {"id": "f3", "type": "textarea", "label": "What I would like to have back"}, {"id": "f4", "type": "textarea", "label": "A small step toward it that feels possible"}, {"id": "f5", "type": "textarea", "label": "What I will do if it feels too much"}]'::jsonb, array['social anxiety', 'avoidance', 'exposure', 'values']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('anniversary-ritual-designer-1005c', 'Anniversary Ritual Designer', 'worksheet'::resource_kind, 'A planning sheet for shaping a meaningful ritual around a birthday, anniversary or holiday after a loss.', 'Help a client plan a chosen way to mark a hard date with support.', array['Adults', 'Teens']::text[], '25 minutes', 'Use this before a hard date, such as a birthday, to help the client choose how they would like to mark it, who to invite and what to do if feelings rise. Rituals can be tiny. Respect that some clients want nothing, which is also a plan. Check how realistic their plan is and what support they have.', '[{"id": "f0", "type": "textarea", "label": "The date I want to plan for"}, {"id": "f1", "type": "textarea", "label": "What I would like the day to hold"}, {"id": "f2", "type": "textarea", "label": "Who I would like to share it with"}, {"id": "f3", "type": "textarea", "label": "Something that reminds me of the person or what I lost"}, {"id": "f4", "type": "textarea", "label": "What I will do if the feelings are heavy"}, {"id": "f5", "type": "textarea", "label": "A person I can reach out to afterward"}]'::jsonb, array['grief and loss', 'rituals', 'planning', 'bereavement']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('grief-five-senses-comfort-kit-1005c', 'Grief Five Senses Comfort Kit', 'dbt'::resource_kind, 'A self-soothing kit built from the five senses to use during waves of grief.', 'Help a client build a ready kit of comforts for waves of grief.', array['Adults', 'Teens']::text[], '25 minutes', 'Walk through each sense and have the client pick one thing that soothes without avoiding the grief, such as a scent, a song or a soft blanket. Prepare the kit in session so it is ready before a wave arrives. Reinforce that comfort is not forgetting. If a client mentions thoughts of harming themselves, move to your own safety steps in session.', '[{"id": "f0", "type": "textarea", "label": "Something I can see that comforts me"}, {"id": "f1", "type": "textarea", "label": "Something I can hear that comforts me"}, {"id": "f2", "type": "textarea", "label": "Something I can smell that comforts me"}, {"id": "f3", "type": "textarea", "label": "Something I can taste that comforts me"}, {"id": "f4", "type": "textarea", "label": "Something I can touch that comforts me"}, {"id": "f5", "type": "textarea", "label": "Where I will keep my kit so it is easy to find"}]'::jsonb, array['grief and loss', 'self-soothing', 'skills', 'regulation']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('grief-feelings-color-map-1005c', 'Grief Feelings Color Map', 'kids'::resource_kind, 'A child colors a body outline with the feelings of grief and talks with a parent about each color.', 'Help a child name grief feelings through color and share them with a parent.', array['Children']::text[], '30 minutes', 'Give the child a body outline and invite them to choose colors for feelings like sad, mad, worried and missing. They fill in where they feel each one. The parent listens and says what they notice without fixing. Let the child lead and stop whenever they wish. If a child discloses anything worrying, remember your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "The feelings I have about our loss"}, {"id": "f1", "type": "textarea", "label": "The color I picked for each one"}, {"id": "f2", "type": "textarea", "label": "Where I feel each one in my body"}, {"id": "f3", "type": "textarea", "label": "What I do when the feeling is big"}, {"id": "f4", "type": "textarea", "label": "Who I can tell when I feel this way"}, {"id": "f5", "type": "textarea", "label": "What my parent will do to help"}]'::jsonb, array['grief and loss', 'children', 'art', 'family']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('pain-of-love-valuing-practice-1005c', 'Pain of Love Valuing Practice', 'act'::resource_kind, 'A practice linking the pain of loss to what the client valued in the person and in their life.', 'Help a client hold grief and love together and choose values-based actions.', array['Adults']::text[], '25 minutes', 'Invite the client to notice that grief is bound up with what mattered, then name the values the relationship embodied. Choose one small action that carries a value forward, such as kindness or humor, while the pain is present. Avoid rushing toward meaning. Let them lead and use your own judgment about pace.', '[{"id": "f0", "type": "textarea", "label": "What I miss most about the person or what I lost"}, {"id": "f1", "type": "textarea", "label": "The value that relationship stood for"}, {"id": "f2", "type": "textarea", "label": "How the pain and love feel together"}, {"id": "f3", "type": "textarea", "label": "One small way I could carry that value forward"}, {"id": "f4", "type": "textarea", "label": "What gets in the way"}, {"id": "f5", "type": "textarea", "label": "Who could join me in this"}]'::jsonb, array['grief and loss', 'values', 'acceptance', 'core ACT']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('hard-day-prediction-check-1005c', 'Hard Day Prediction Check', 'cbt'::resource_kind, 'A sheet comparing predictions about a hard day with what actually happened afterward.', 'Help a client test predictions about difficult dates and notice what helped.', array['Adults']::text[], '20 minutes', 'Before a hard day, the client writes predictions about how it will go and what they will not be able to handle. Afterward, they record what happened and what helped. Reflect on the gap with curiosity, but never push the idea that grief should feel better. Use it as a conversation starter in your own formulation.', '[{"id": "f0", "type": "textarea", "label": "The hard day I am preparing for"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen"}, {"id": "f2", "type": "textarea", "label": "How strongly I believe it, from 0 to 100"}, {"id": "f3", "type": "textarea", "label": "What helped me get through it"}, {"id": "f4", "type": "textarea", "label": "What actually happened"}, {"id": "f5", "type": "textarea", "label": "What I want to remember for next time"}]'::jsonb, array['grief and loss', 'predictions', 'planning', 'core CBT']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('weekly-state-of-us-check-in-1005d', 'Weekly State of Us Check-In', 'worksheet'::resource_kind, 'A short weekly sheet for one partner to name what felt close, what felt strained, and one small request.', 'Give a client a steady, low-stakes way to bring relationship concerns into session.', array['Adults']::text[], '15 minutes weekly', 'Have the client fill this in once a week, ideally on the same day, and bring it to session. It gives you a quick read on what the client notices about the relationship over time without turning each week into a verdict. Watch for requests that are really complaints, and help the client reshape them into something specific and doable.', '[{"id": "f0", "type": "textarea", "label": "One moment this week when I felt close to my partner"}, {"id": "f1", "type": "textarea", "label": "One moment when I felt distant or tense"}, {"id": "f2", "type": "textarea", "label": "What I was feeling and needing in that tense moment"}, {"id": "f3", "type": "textarea", "label": "One small, doable request I could make this week"}, {"id": "f4", "type": "textarea", "label": "One thing I will do on my side"}]'::jsonb, array['relationship issues', 'communication', 'monitoring']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('give-skill-rehearsal-card-1005d', 'GIVE Skill Rehearsal Card', 'dbt'::resource_kind, 'A rehearsal card for the GIVE interpersonal skill, gentle, interested, validate, easy manner, in one real conversation.', 'Help a client practice keeping the relationship intact while raising a hard topic.', array['Adults', 'Teens']::text[], '20 minutes', 'Walk the client through each letter of GIVE, then rehearse the opening minute of a real upcoming conversation in session. Clients often hear gentle as giving in, so name the difference. Have them pick just one or two letters to focus on first, and debrief on how the practice felt in the body as well as in the words.', '[{"id": "f0", "type": "textarea", "label": "The conversation I want to have, and with whom"}, {"id": "f1", "type": "textarea", "label": "How I can be gentle in my first sentence"}, {"id": "f2", "type": "textarea", "label": "A question showing I am interested in their side"}, {"id": "f3", "type": "textarea", "label": "Something I can validate, even if I disagree"}, {"id": "f4", "type": "textarea", "label": "What an easy manner would look like for me"}, {"id": "f5", "type": "textarea", "label": "Which letter is hardest, and what might help"}]'::jsonb, array['relationship issues', 'interpersonal effectiveness', 'skills', 'communication']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('partner-mind-reading-check-1005d', 'Partner Assumption Check-Out Sheet', 'cbt'::resource_kind, 'A thought sheet that separates what a partner did from the story the client adds about why.', 'Help a client notice assumptions about a partner''s motives and test them gently.', array['Adults']::text[], '20 minutes', 'Use this after a recent moment of hurt or irritation. The client separates the observable event from the meaning they assigned, then rates how sure they feel and lists other possible explanations. The aim is a wider view, not proof that the partner meant well. Pair it with a plan to ask the partner directly when it feels safe to do so.', '[{"id": "f0", "type": "textarea", "label": "What my partner said or did, as a camera would record it"}, {"id": "f1", "type": "textarea", "label": "The story I told myself about why"}, {"id": "f2", "type": "textarea", "label": "How sure I felt in that story, 0 to 100"}, {"id": "f3", "type": "textarea", "label": "Two other things that could explain it"}, {"id": "f4", "type": "textarea", "label": "What I could ask my partner to find out"}, {"id": "f5", "type": "textarea", "label": "How I feel now after looking at it again"}]'::jsonb, array['relationship issues', 'thinking traps', 'communication', 'core CBT']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('soft-startup-rewrite-game-1005d', 'Soft Startup Rewrite Game', 'game'::resource_kind, 'A turn-taking card game where players rewrite harsh complaint openers into gentler, specific ones.', 'Build fluency with raising a concern without blame, using humor and low stakes.', array['Couples', 'Groups']::text[], '25 minutes', 'Write a dozen harsh openers on cards, such as ''You never help.'' Players take turns drawing one and rewriting it as a soft startup: feeling, situation, small request. The group votes on the version that would land best. In the debrief, ask what made the rewrites easier or harder, and let couples try one on a real topic only if they choose to.', '[{"id": "f0", "type": "textarea", "label": "The harshest opener I drew"}, {"id": "f1", "type": "textarea", "label": "My rewrite using a feeling, a situation, and a request"}, {"id": "f2", "type": "textarea", "label": "What the group liked about the best rewrite"}, {"id": "f3", "type": "textarea", "label": "What was hard about softening it"}, {"id": "f4", "type": "textarea", "label": "A real concern I could raise with a soft start this week"}]'::jsonb, array['relationship issues', 'Gottman', 'communication', 'play']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('family-meeting-talking-stick-craft-1005d', 'Family Meeting Speaking Token Craft', 'kids'::resource_kind, 'A child decorates a talking stick that is passed around at family meetings so everyone gets a turn.', 'Give a family a concrete cue for taking turns when something needs to be discussed.', array['Children', 'Adults']::text[], '30 minutes', 'The child decorates a stick or cardboard tube with drawings of what makes a good listener. The parent then explains the rule: only the holder talks, and everyone else listens. Try it in session with a light topic like a weekend plan. Parents should model waiting and reflecting back what they heard, and keep early meetings short and positive.', '[{"id": "f0", "type": "textarea", "label": "Draw or write what a good listener does"}, {"id": "f1", "type": "textarea", "label": "Draw or write what I want my family to know about me"}, {"id": "f2", "type": "textarea", "label": "One thing that would make our home feel calmer"}, {"id": "f3", "type": "textarea", "label": "One fun topic for our first family meeting"}, {"id": "f4", "type": "textarea", "label": "What the parent will do to keep the stick rule fair"}]'::jsonb, array['relationship issues', 'children', 'family', 'communication']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('pacing-dial-for-hard-days-1005d', 'Pacing Dial for Hard Days', 'worksheet'::resource_kind, 'A simple dial sheet that helps a client decide how much to take on today and what to set aside.', 'Support a client in pacing daily demands and choosing gentler options on hard days.', array['Adults']::text[], '15 minutes', 'Introduce this as a way to keep the client in charge of pace, not a measure of progress. The client rates how today feels, then sorts tasks into do now, do small, and wait. It stays entirely in the present and asks for no account of the past. Revisit it in session so the client can notice that slowing down is a choice and a skill.', '[{"id": "f0", "type": "textarea", "label": "On a scale of 1 to 10, how hard does today feel"}, {"id": "f1", "type": "textarea", "label": "What I need to get done today no matter what"}, {"id": "f2", "type": "textarea", "label": "What I can do in a smaller way today"}, {"id": "f3", "type": "textarea", "label": "What can wait until a steadier day"}, {"id": "f4", "type": "textarea", "label": "One kind thing I will do for myself tonight"}, {"id": "f5", "type": "textarea", "label": "Who I could reach out to if today gets heavier"}]'::jsonb, array['sexual abuse', 'pacing', 'safety', 'support']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('window-of-tolerance-check-in-1005d', 'Window of Tolerance Check-In', 'dbt'::resource_kind, 'A card for noticing whether the body is too revved up, too shut down, or steady, and picking a skill to match.', 'Help a client name their present-moment state and choose a stabilizing skill.', array['Adults', 'Teens']::text[], '15 minutes', 'Teach the idea of a steady zone with revved-up and shut-down edges, then have the client mark where they are right now. Match each state with a skill the client already knows, such as cold water for revved-up or movement for shut-down. Keep it about the present moment only. Practice in session so the client trusts the card before they use it alone.', '[{"id": "f0", "type": "textarea", "label": "Where my body is right now: revved up, steady, or shut down"}, {"id": "f1", "type": "textarea", "label": "Signs in my body that tell me this"}, {"id": "f2", "type": "textarea", "label": "A skill that fits when I am revved up"}, {"id": "f3", "type": "textarea", "label": "A skill that fits when I feel shut down"}, {"id": "f4", "type": "textarea", "label": "A skill that keeps me steady"}, {"id": "f5", "type": "textarea", "label": "Where I will keep this card so I can find it"}]'::jsonb, array['sexual abuse', 'grounding', 'regulation', 'distress tolerance']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('anchors-in-the-present-practice-1005d', 'Anchors in the Present Practice', 'act'::resource_kind, 'A dropping-anchor style exercise to feel feet, notice surroundings, and return to the room when old reminders surface.', 'Give a client a short way to come back to the present without having to push anything away.', array['Adults']::text[], '10 minutes', 'Guide the client through noticing their feet, their breath, and five things in the room, while letting any thoughts or feelings be present without engaging them. Offer eyes open as the default and let the client choose. Do not ask what the reminder was about. Practice in session first, then suggest short rehearsals at calm moments rather than only during hard ones.', '[{"id": "f0", "type": "textarea", "label": "What I noticed when I pressed my feet into the floor"}, {"id": "f1", "type": "textarea", "label": "Five things I could see in the room"}, {"id": "f2", "type": "textarea", "label": "What I could hear or feel against my skin"}, {"id": "f3", "type": "textarea", "label": "Thoughts or feelings that showed up while I stayed here"}, {"id": "f4", "type": "textarea", "label": "Where I might use this during my week"}, {"id": "f5", "type": "textarea", "label": "What helps me stay with it comfortably"}]'::jsonb, array['sexual abuse', 'core ACT', 'grounding', 'mindfulness']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('safe-people-hand-map-1005d', 'Circle of Trusted Adults Hand Map', 'kids'::resource_kind, 'A child traces a hand and writes or draws a trusted adult on each finger to name who they could tell.', 'Help a child identify trusted adults and practice who they would go to if something felt wrong.', array['Children']::text[], '20 minutes', 'The child traces a hand and draws or names five trusted adults, one per finger, with the parent. Keep the tone calm and matter-of-fact, focused on who helps rather than on what might happen. If a child discloses anything, stay calm, believe them, and follow your reporting duties. Parents should keep the map somewhere visible at home.', '[{"id": "f0", "type": "textarea", "label": "Draw or write one grown-up I trust at home"}, {"id": "f1", "type": "textarea", "label": "Draw or write one grown-up I trust at school"}, {"id": "f2", "type": "textarea", "label": "Draw or write one grown-up in my family I could tell"}, {"id": "f3", "type": "textarea", "label": "What I can say if something feels wrong or yucky"}, {"id": "f4", "type": "textarea", "label": "What I can do to get to a trusted grown-up fast"}, {"id": "f5", "type": "textarea", "label": "What my parent will do when I tell them something"}]'::jsonb, array['sexual abuse', 'children', 'body safety', 'support']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('safe-person-evidence-sheet-1005d', 'Safe Person Evidence Sheet', 'cbt'::resource_kind, 'A sheet for gathering present-day evidence about who in a client''s life has shown steady, respectful behavior.', 'Help a client notice trustworthy behavior in the present when trust feels hard to calibrate.', array['Adults']::text[], '20 minutes', 'Many clients find trust swings between all and nothing. This sheet lists specific behaviors a person has shown over time, such as keeping their word or respecting a no, rather than rating the person as safe or unsafe. Go at the client''s pace and never ask for details of past events. Use it to plan small, chosen steps of closeness.', '[{"id": "f0", "type": "textarea", "label": "A person in my life I am considering"}, {"id": "f1", "type": "textarea", "label": "Times they respected a boundary or a no"}, {"id": "f2", "type": "textarea", "label": "Times they kept their word"}, {"id": "f3", "type": "textarea", "label": "Times I felt uneasy, and what exactly happened"}, {"id": "f4", "type": "textarea", "label": "What this suggests about how much to share for now"}, {"id": "f5", "type": "textarea", "label": "A small step I choose, and a step I will not take yet"}]'::jsonb, array['sexual abuse', 'boundaries', 'core CBT', 'support']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('coping-skill-weather-forecast-1005d', 'Coping Skill Weather Forecast', 'worksheet'::resource_kind, 'A planning sheet that matches coping skills to emotional weather: sunny, cloudy, stormy, and foggy days.', 'Help a client build a ready plan so the right skill is easy to find in each emotional state.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client name what each kind of day feels like in the body and mind, then choose one or two skills for each. The metaphor makes the plan easy to remember and lets the client notice that different days call for different tools. Revisit it after a week and swap out anything that did not help, without treating that as failure.', '[{"id": "f0", "type": "textarea", "label": "What a sunny day feels like for me, and a skill to keep it going"}, {"id": "f1", "type": "textarea", "label": "What a cloudy day feels like, and a skill that helps"}, {"id": "f2", "type": "textarea", "label": "What a stormy day feels like, and a skill for it"}, {"id": "f3", "type": "textarea", "label": "What a foggy day feels like, and a skill for it"}, {"id": "f4", "type": "textarea", "label": "Which forecast I think I am in this week"}, {"id": "f5", "type": "textarea", "label": "Who or what could help me if the weather stays rough"}]'::jsonb, array['coping skills', 'regulation', 'planning', 'skills']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('thought-then-skill-pairing-card-1005d', 'Thought-Then-Skill Pairing Card', 'cbt'::resource_kind, 'A card pairing common unhelpful thoughts with a coping skill and a more balanced thought to say next.', 'Link a client''s recurring thoughts to a skill so the response is ready before the moment hits.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client for two or three thoughts that come up often when stress rises, then pair each with a skill and a balanced alternative. Rehearse reading the card aloud in session. The card works best when the balanced thought sounds like the client, not like a slogan, so edit the wording together until it fits.', '[{"id": "f0", "type": "textarea", "label": "A thought that shows up when I am stressed"}, {"id": "f1", "type": "textarea", "label": "A skill I can use when I notice it"}, {"id": "f2", "type": "textarea", "label": "A balanced thought I can tell myself"}, {"id": "f3", "type": "textarea", "label": "A second thought that shows up"}, {"id": "f4", "type": "textarea", "label": "A skill and balanced thought for that one"}, {"id": "f5", "type": "textarea", "label": "Where I will keep this card"}]'::jsonb, array['coping skills', 'self-talk', 'thinking traps', 'core CBT']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('dropping-anchor-for-hard-moments-1005d', 'Dropping Anchor for Hard Moments', 'act'::resource_kind, 'A brief exercise to feel the body, notice surroundings, and choose a next step while a hard feeling is present.', 'Teach a client a portable way to steady themselves without needing the feeling to go away.', array['Adults', 'Teens']::text[], '10 minutes', 'Lead the client through acknowledging what is showing up, connecting with the body by pushing feet down or stretching, and then noticing the room and engaging in the next task. Stress that the feeling does not have to leave. Have the client practice it twice in session and rate how it felt, then pick two moments in the week to try it.', '[{"id": "f0", "type": "textarea", "label": "What I notice showing up inside right now"}, {"id": "f1", "type": "textarea", "label": "What I did to connect with my body"}, {"id": "f2", "type": "textarea", "label": "What I noticed around me in the room"}, {"id": "f3", "type": "textarea", "label": "What I want to do next that matters to me"}, {"id": "f4", "type": "textarea", "label": "A moment this week where I will try this"}, {"id": "f5", "type": "textarea", "label": "How it went when I tried it"}]'::jsonb, array['coping skills', 'core ACT', 'mindfulness', 'acceptance']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('tipp-skill-practice-card-1005d', 'TIPP Skill Practice Card', 'dbt'::resource_kind, 'A practice card for the TIPP skills, temperature, intense exercise, paced breathing, and paired muscle relaxation.', 'Let a client try each fast-acting body skill in a calm moment so they can reach for it under stress.', array['Adults', 'Teens']::text[], '25 minutes', 'Go through each TIPP skill and let the client try a short version in session when they are calm, with their own consent and comfort. Check for any health concerns with the client before cold water or exercise. Clients often skip practice until they are in distress, so schedule rehearsals and have them note which skill suited them best.', '[{"id": "f0", "type": "textarea", "label": "How I felt in my body before trying a skill"}, {"id": "f1", "type": "textarea", "label": "What happened when I tried cold water or a cold pack"}, {"id": "f2", "type": "textarea", "label": "What happened when I tried brisk movement"}, {"id": "f3", "type": "textarea", "label": "What happened when I tried slow breathing with a longer exhale"}, {"id": "f4", "type": "textarea", "label": "What happened when I tried tensing then relaxing my muscles"}, {"id": "f5", "type": "textarea", "label": "Which skill suits me best, and when I will use it"}]'::jsonb, array['coping skills', 'distress tolerance', 'skills', 'regulation']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('coping-skill-charades-1005d', 'Coping Skill Mime Game', 'game'::resource_kind, 'Players act out a coping skill without words while others guess it, then share when they have used it.', 'Make coping skills memorable and normal to talk about through movement and laughter.', array['Groups', 'Teens']::text[], '25 minutes', 'Write skills on cards, such as walking, calling a friend, or slow breathing. Players take turns acting one out silently while others guess. After each correct guess, the actor says when a similar skill helped them. Debrief by asking which skills people want to try and keep the mood light so nobody feels singled out.', '[{"id": "f0", "type": "textarea", "label": "The skill I acted out"}, {"id": "f1", "type": "textarea", "label": "A time I used this skill or something like it"}, {"id": "f2", "type": "textarea", "label": "A skill someone else acted that I want to try"}, {"id": "f3", "type": "textarea", "label": "What got in the way when I tried skills before"}, {"id": "f4", "type": "textarea", "label": "One skill I will try this week and when"}]'::jsonb, array['coping skills', 'coping skills card', 'play', 'group']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('avoidance-cost-ledger-for-feared-situations-1005d', 'Avoidance Cost Ledger for Feared Situations', 'worksheet'::resource_kind, 'A two-column ledger listing what avoiding a feared situation protects and what it costs the client''s life.', 'Help a client see the full picture of what avoidance has given and taken before choosing steps.', array['Adults']::text[], '20 minutes', 'Have the client list what avoidance gives them, usually relief, and what it takes, such as trips, jobs, or time with people. The ledger does not argue against the fear. It opens a conversation about what the client wants. Let them lead, and use it to decide if and when to build a gradual set of steps together.', '[{"id": "f0", "type": "textarea", "label": "The situation or thing I tend to avoid"}, {"id": "f1", "type": "textarea", "label": "What avoiding it gives me in the moment"}, {"id": "f2", "type": "textarea", "label": "Places, people, or plans avoiding it has cost me"}, {"id": "f3", "type": "textarea", "label": "What I would do if the fear were smaller"}, {"id": "f4", "type": "textarea", "label": "How much this cost matters to me, 0 to 10"}, {"id": "f5", "type": "textarea", "label": "One small step I might consider"}]'::jsonb, array['phobias', 'avoidance', 'values', 'exposure']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('safety-behavior-inventory-1005d', 'Fear-Driven Safety Habits Inventory', 'cbt'::resource_kind, 'A list for noticing small things a client does to feel safe around a feared situation and what each one teaches the mind.', 'Help a client spot subtle protective habits that keep the fear feeling necessary.', array['Adults', 'Teens']::text[], '20 minutes', 'Safety behaviors can be quiet, like carrying a phone, sitting by the exit, or staying with someone. Ask the client to list theirs and mark which are used most. Explore, without pressure, how each one may keep the fear going. Choose one small behavior to drop in a planned step, and check how the client feels before and after.', '[{"id": "f0", "type": "textarea", "label": "A situation that makes me afraid"}, {"id": "f1", "type": "textarea", "label": "Things I do to feel safer in that situation"}, {"id": "f2", "type": "textarea", "label": "Which of these I use almost every time"}, {"id": "f3", "type": "textarea", "label": "What I fear would happen if I did not do them"}, {"id": "f4", "type": "textarea", "label": "One I might try dropping in a small planned step"}, {"id": "f5", "type": "textarea", "label": "What I noticed when I tried it"}]'::jsonb, array['phobias', 'avoidance', 'exposure', 'behavioral experiment']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('willing-steps-toward-a-feared-situation-1005d', 'Willing Steps Toward a Feared Situation', 'act'::resource_kind, 'A sheet connecting a client''s values to one small step toward a feared situation, with room for fear to come along.', 'Help a client choose a step they are willing to take with fear present, tied to what matters.', array['Adults']::text[], '20 minutes', 'Begin with what the client would want to be doing if fear took up less space, then name one small step toward it. Make willingness the focus: the fear may come along. Let the client set the size of the step and a plan for what they will do with thoughts and sensations that show up. Review without judgment, whether or not the step happened.', '[{"id": "f0", "type": "textarea", "label": "What matters to me that this fear gets in the way of"}, {"id": "f1", "type": "textarea", "label": "A small step toward it that I am willing to take"}, {"id": "f2", "type": "textarea", "label": "Thoughts and feelings I expect to come along"}, {"id": "f3", "type": "textarea", "label": "What I will do when those show up"}, {"id": "f4", "type": "textarea", "label": "When and where I will take the step"}, {"id": "f5", "type": "textarea", "label": "What I noticed and learned afterward"}]'::jsonb, array['phobias', 'willingness', 'values', 'committed action']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('fear-thermometer-craft-1005d', 'Fear Thermometer Craft', 'kids'::resource_kind, 'A child builds a paper thermometer to show how big a fear feels and move the marker as they practice.', 'Give a child a visual, playful way to show how big a fear feels and to notice it changing.', array['Children']::text[], '25 minutes', 'The child builds a paper thermometer with a sliding marker and colors each level, with the parent helping. During practice, the child moves the marker to show how big the fear feels, and the parent responds with calm curiosity rather than reassurance. Choose small steps together, and praise brave tries over results. If a child discloses unsafe situations, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw or write what I am afraid of"}, {"id": "f1", "type": "textarea", "label": "Where the marker is when I think about it"}, {"id": "f2", "type": "textarea", "label": "What my body feels like at that level"}, {"id": "f3", "type": "textarea", "label": "A tiny brave step I could try with my grown-up"}, {"id": "f4", "type": "textarea", "label": "What my grown-up will do while I try"}, {"id": "f5", "type": "textarea", "label": "Where the marker was after I tried"}]'::jsonb, array['phobias', 'children', 'exposure', 'parenting']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('brave-dice-challenge-1005d', 'Brave Dice Challenge', 'game'::resource_kind, 'A dice game where each roll picks a small brave step from a list the client built, with a debrief after each turn.', 'Make gradual practice feel playful and shared, with the client in charge of the steps.', array['Adults', 'Teens', 'Children']::text[], '30 minutes', 'Before play, the client and clinician list six steps from easier to harder and number them. On each turn the client rolls and tries the matching step, or passes or swaps it for one of equal size. Take turns doing a small brave act of your own to share the risk. In the debrief, ask what they noticed, not whether it was done right.', '[{"id": "f0", "type": "textarea", "label": "The six steps on my dice list, easiest to hardest"}, {"id": "f1", "type": "textarea", "label": "The step I rolled and how I felt before it"}, {"id": "f2", "type": "textarea", "label": "What happened when I tried it"}, {"id": "f3", "type": "textarea", "label": "What I learned about the fear"}, {"id": "f4", "type": "textarea", "label": "A step I want to add or change"}, {"id": "f5", "type": "textarea", "label": "What I want to practice before our next session"}]'::jsonb, array['phobias', 'exposure', 'hierarchy', 'play']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('compliment-redirect-sheet-1005d', 'Compliment Redirect Sheet', 'worksheet'::resource_kind, 'A sheet for noticing appearance compliments and comments and practicing replies that move toward other topics.', 'Help a client respond to appearance talk in ways that fit their values.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to collect times they hear appearance comments or give them. Together, brainstorm replies that are simple and true, such as a thank-you and a topic change. Rehearse a few aloud in session. This does not tell the client what to feel about their body. It gives them more choices about the conversations they join.', '[{"id": "f0", "type": "textarea", "label": "A recent time someone commented on appearance"}, {"id": "f1", "type": "textarea", "label": "How I felt in that moment"}, {"id": "f2", "type": "textarea", "label": "How I responded"}, {"id": "f3", "type": "textarea", "label": "A reply I would like to have ready next time"}, {"id": "f4", "type": "textarea", "label": "A topic I would rather talk about"}, {"id": "f5", "type": "textarea", "label": "Who I could practice this reply with"}]'::jsonb, array['body image', 'social comparison', 'communication', 'habits']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('comparison-trigger-thought-record-1005d', 'Comparison Trigger Thought Record', 'cbt'::resource_kind, 'A thought record for moments of comparing appearance to others, separating the trigger, the thought, and a wider view.', 'Help a client slow down automatic comparisons and respond with a more balanced thought.', array['Adults', 'Teens']::text[], '20 minutes', 'Use this when the client reports comparing themselves to others online or in person. They record the trigger, the automatic thought, and the emotion, then look at what the comparison leaves out and what they would say to a friend. Do not push for positive thoughts. A believable, balanced one is enough, and the client can rate how much they believe it.', '[{"id": "f0", "type": "textarea", "label": "Where I was and what set off the comparison"}, {"id": "f1", "type": "textarea", "label": "The thought that popped up"}, {"id": "f2", "type": "textarea", "label": "How I felt, and how strongly, 0 to 100"}, {"id": "f3", "type": "textarea", "label": "What this comparison leaves out"}, {"id": "f4", "type": "textarea", "label": "What I would say to a friend who had this thought"}, {"id": "f5", "type": "textarea", "label": "How I feel now, 0 to 100"}]'::jsonb, array['body image', 'social comparison', 'thinking traps', 'core CBT']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('values-beyond-appearance-collage-1005d', 'Values Beyond Appearance Collage', 'act'::resource_kind, 'A collage activity connecting the person a client wants to be to actions that do not depend on how they look.', 'Help a client put their energy toward values-led living, with appearance as one part of the picture.', array['Adults', 'Teens']::text[], 'Full session', 'The client gathers images, words, or drawings for what they care about, such as friendship, creativity, or curiosity, and then links each to an action for the coming week. Thoughts about appearance may show up while they work, so practice noticing them and returning to the task. Keep the focus on direction, not on convincing the client to like how they look.', '[{"id": "f0", "type": "textarea", "label": "Three things that matter most to me"}, {"id": "f1", "type": "textarea", "label": "An image or word for each of them"}, {"id": "f2", "type": "textarea", "label": "Thoughts about my looks that showed up while I worked"}, {"id": "f3", "type": "textarea", "label": "What I did when those thoughts showed up"}, {"id": "f4", "type": "textarea", "label": "An action this week that fits one of my values"}, {"id": "f5", "type": "textarea", "label": "What I would do if appearance thoughts came along"}]'::jsonb, array['body image', 'values', 'defusion', 'committed action']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('opposite-action-for-hiding-practice-1005d', 'Opposite Action for Hiding Practice', 'dbt'::resource_kind, 'A card walking a client through using opposite action when shame about appearance urges hiding or avoiding.', 'Help a client act against urges to hide or avoid, in small and chosen ways.', array['Adults', 'Teens']::text[], '20 minutes', 'Teach opposite action: when an emotion urges a behavior that does not fit the situation, act in the opposite way. Have the client list hiding urges, such as skipping events or covering up, and pick one small opposite step. First check whether the emotion fits the facts. Debrief after the step on what shifted, with no pressure for a particular result.', '[{"id": "f0", "type": "textarea", "label": "The emotion I felt and what set it off"}, {"id": "f1", "type": "textarea", "label": "The urge to hide or avoid that came with it"}, {"id": "f2", "type": "textarea", "label": "Whether the emotion fits the facts of the situation"}, {"id": "f3", "type": "textarea", "label": "A small opposite action I could take"}, {"id": "f4", "type": "textarea", "label": "When and where I will do it"}, {"id": "f5", "type": "textarea", "label": "What I noticed afterward"}]'::jsonb, array['body image', 'emotion regulation', 'avoidance', 'skills']::text[], '2026-10-05T15:00:00+00:00'::timestamptz),
  ('superpower-body-badge-craft-1005d', 'Superpower Body Badge Craft', 'kids'::resource_kind, 'A child designs a badge showing something their body can do that they are proud of, such as running, hugging, or laughing.', 'Help a child build pride in what their body does, in a way that is playful and not about looks.', array['Children']::text[], '25 minutes', 'The child decorates a badge naming a body superpower, such as strong legs for jumping or hands for building. The parent joins by making a badge too, using a function and not appearance. Talk about how bodies are different and that each one is useful in its own ways. Parents should model this kind of talk at home and avoid commenting on looks, their own included.', '[{"id": "f0", "type": "textarea", "label": "My body superpower"}, {"id": "f1", "type": "textarea", "label": "A time my body helped me do something fun"}, {"id": "f2", "type": "textarea", "label": "Draw a picture of my badge"}, {"id": "f3", "type": "textarea", "label": "A superpower someone in my family has"}, {"id": "f4", "type": "textarea", "label": "How I can thank my body today"}]'::jsonb, array['body image', 'children', 'play', 'self-esteem']::text[], '2026-10-05T15:00:00+00:00'::timestamptz)
